INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C1','math',2,2,'u4',2,'5분 단위로 시각 읽기 — 짧은바늘로 시를, 긴바늘이 가리키는 숫자에 5를 곱해 분을 읽어 「몇 시 몇 분」으로 나타내기',ARRAY['2수03-05']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C2','math',2,2,'u4',2,'디지털시계 읽기 — 「:」 왼쪽은 시, 오른쪽은 분임을 알고 「열 시 삼십오 분」처럼 바르게 읽고 바늘 시계와 같은 시각을 찾기',ARRAY['2수03-05']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C3','math',2,2,'u4',3,'1분 단위로 시각 읽기 — 작은 눈금 한 칸이 1분임을 알고, 가까운 숫자에서 몇 칸 더(덜) 갔는지 세어 몇 시 몇 분을 읽기',ARRAY['2수03-05']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C4','math',2,2,'u4',4,'몇 시 몇 분 전 — 정각이 되기까지 남은 분을 세어 「몇 시 몇 분 전」으로 읽고, 「몇 시 몇 분 전」을 「몇 시 몇 분」으로 바꾸기',ARRAY['2수03-05']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C5','math',2,2,'u4',5,'1시간 알기 — 긴바늘이 한 바퀴 도는 데 60분이 걸리고 60분 = 1시간임을 알며, 시간 띠(한 칸 10분)로 걸린 시간을 세기',ARRAY['2수03-06']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C6','math',2,2,'u4',6,'걸린 시간 구하기 — 1시간을 먼저 돌리고 더 간 만큼 세어 걸린 시간을 구하고, 몇 시간 몇 분과 몇 분을 서로 바꾸기',ARRAY['2수03-06']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C7','math',2,2,'u4',7,'하루의 시간 — 하루는 24시간이고 오전·오후가 각각 12시간임을 알며, 생활 계획표로 하는 일의 시간을 알고, 하루가 넘는 시간과 오전·오후를 넘는 시각을 구하기',ARRAY['2수03-06']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C8','math',2,2,'u4',8,'달력과 1주일 — 달력에서 날짜와 요일을 읽고, 1주일 = 7일을 써서 몇째 무슨 요일·며칠 후(전)·요일의 횟수를 찾기',ARRAY['2수03-06']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C9','math',2,2,'u4',8,'1년과 달의 날수 — 1년 = 12개월임을 알고 몇 년 몇 개월과 몇 개월을 바꾸며, 달마다 날수가 다름을 알고 「몇 월」과 「몇 개월」을 가리기',ARRAY['2수03-06']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u4-C10','math',2,2,'u4',10,'시간으로 문제 해결하기 — 성장 이야기와 디데이를 만들며 년·개월·주·일 사이의 관계로 날짜와 기간을 구하기',ARRAY['2수03-06']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X01','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C3']::text[],'짧은바늘과 긴바늘을 바꾸어 읽는다 — 긴바늘이 가리키는 숫자를 시로, 짧은바늘을 분으로 읽는다','짧은바늘은 시, 긴바늘은 분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X02','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C2','M2-2-u4-C3']::text[],'긴바늘이 가리키는 숫자를 그대로 분으로 읽는다(숫자 3 → 3분)','긴바늘 숫자에 5를 곱하기 — 숫자 1이 5분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X03','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C3','M2-2-u4-C4']::text[],'짧은바늘이 다음 숫자 가까이 있으면 다음 시로 읽는다(4시 55분 → 5시 55분)','짧은바늘이 지나온 숫자가 시 — 아직 다음 숫자에 닿지 않았어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X04','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C2','M2-2-u4-C3']::text[],'이웃 눈금·이웃 숫자로 잘못 읽어 1분·5분 어긋나게 읽는다','눈금을 손가락으로 짚으며 한 칸씩 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X05','math',2,'u4',ARRAY['M2-2-u4-C3']::text[],'숫자에서 몇 칸 「더 간」 곳과 「덜 간」 곳을 거꾸로 센다(40분에서 1칸 덜 간 곳 → 41분)','시계 방향은 더 가기, 거꾸로는 덜 가기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X06','math',2,'u4',ARRAY['M2-2-u4-C2']::text[],'디지털시계의 시와 분을 뒤바꾸거나 읽는 말을 잘못 쓴다(10 : 35 → 「십 시」, 「삼십오 시 열 분」)','「:」 왼쪽은 시 「한·두·세」, 오른쪽은 분 「일·이·삼」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X07','math',2,'u4',ARRAY['M2-2-u4-C4']::text[],'「몇 시 몇 분 전」의 시를 곧 될 정각이 아니라 지금 시로 쓴다(8시 55분 → 8시 5분 전)','「전」의 시는 곧 될 정각 — 지금 시보다 하나 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X08','math',2,'u4',ARRAY['M2-2-u4-C4']::text[],'정각까지 남은 분 대신 지난 분을 쓰거나 「전」을 빼고 읽는다(8시 55분 → 9시 55분 전, 9시 5분 전 → 9시 5분)','정각까지 몇 분 남았는지 세기 — 「전」은 꼭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X09','math',2,'u4',ARRAY['M2-2-u4-C5','M2-2-u4-C6']::text[],'1시간을 100분으로 보고 시간과 분을 바꾼다(1시간 10분 → 110분)','1시간은 60분 — 긴바늘 한 바퀴') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X10','math',2,'u4',ARRAY['M2-2-u4-C4','M2-2-u4-C5','M2-2-u4-C6','M2-2-u4-C7','M2-2-u4-C9','M2-2-u4-C10']::text[],'걸린 시간·지난 시각을 셀 때 칸·시간을 하나 더 세거나 덜 센다','시작에서 한 칸씩 짚으며 다시 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X11','math',2,'u4',ARRAY['M2-2-u4-C5','M2-2-u4-C6']::text[],'시각과 시간을 섞는다 — 끝난 시각을 걸린 시간으로 답하거나, 몇 시를 몇 시간으로 읽는다','시각은 「때」, 시간은 「동안」 — 시작과 끝 사이를 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X12','math',2,'u4',ARRAY['M2-2-u4-C7']::text[],'낮 12시를 넘어도 오전으로 쓰거나 13시·14시처럼 그대로 이어 쓰고, 오전·오후를 뒤바꾼다','낮 12시를 지나면 오후 1시부터 다시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X13','math',2,'u4',ARRAY['M2-2-u4-C7']::text[],'하루를 12시간으로 알거나, 하는 일이 많은 쪽이 더 길다고 여긴다','짧은바늘 두 바퀴 = 24시간 — 오전도 오후도 12시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X14','math',2,'u4',ARRAY['M2-2-u4-C8','M2-2-u4-C9','M2-2-u4-C10']::text[],'날짜의 이름과 기간의 길이를 섞는다 — 「12월」과 「12개월」, 그날의 날짜와 지난 날수를 같게 본다','「월·일」은 이름, 「개월·일 동안」은 길이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X15','math',2,'u4',ARRAY['M2-2-u4-C8','M2-2-u4-C9','M2-2-u4-C10']::text[],'1주일·1년의 단위를 모른다 — 1주일을 5일·10일로, 1년을 10개월로 보거나 주와 일을 그냥 더한다','1주일 = 7일, 1년 = 12개월') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X16','math',2,'u4',ARRAY['M2-2-u4-C1','M2-2-u4-C2','M2-2-u4-C3','M2-2-u4-C4','M2-2-u4-C5','M2-2-u4-C6','M2-2-u4-C7','M2-2-u4-C8','M2-2-u4-C9','M2-2-u4-C10']::text[],'묻는 말을 거꾸로 읽는다 — 잘못된↔바른, 아닌↔맞는, 이른↔늦은','물음의 「잘못·아닌·이른」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X17','math',2,'u4',ARRAY['M2-2-u4-C8','M2-2-u4-C10']::text[],'달력에서 며칠 후(전)를 셀 때 그날을 넣어 세거나, 요일 칸을 하나 밀려 읽는다','그날은 빼고 다음 날부터 하루씩 — 요일은 세로줄 위를 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u4-X18','math',2,'u4',ARRAY['M2-2-u4-C9','M2-2-u4-C10']::text[],'달마다 날수가 다름을 모른다 — 모든 달을 30일로 보거나 달을 넘어가는 날짜를 그대로 쓴다(7월 47일)','31일·30일 달을 주먹 손등으로 세기 — 넘치면 다음 달') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#1','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',1,'mc','auto','긴바늘이 숫자 4를 가리키면 몇 분인가요?',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"긴바늘이 숫자 4를 가리키면 몇 분인가요?","explanation":["숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","숫자 4까지 5분씩 4번이니 4 × 5 = 20이에요.","그래서 20분이에요 — 숫자 그대로 4분이 아니에요."],"variant_rule":{"tm":{"ask":"numm"}},"options":[{"t":"20분","correct":true},{"t":"4분","mis":"M2-2-u4-X02"},{"t":"40분","mis":"M2-2-u4-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#2','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X02','M2-2-u4-X01']::text[],true,'{"seq":2,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 2와 3 사이에 있으니 2시예요.","긴바늘이 숫자 4를 가리키니 4 × 5 = 20분이에요.","그래서 2시 20분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"options":[{"t":"2시 20분","correct":true},{"t":"2시 4분","mis":"M2-2-u4-X02"},{"t":"4시 10분","mis":"M2-2-u4-X01"}],"asset":{"type":"clock2","h":2,"m":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#3','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 7시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 7시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 7과 8 사이에 있으니 7시예요.","긴바늘이 숫자 2를 가리키니 2 × 5 = 10분이에요.","그래서 7시 10분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"answer":["10"],"asset":{"type":"clock2","h":7,"m":10}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#4','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',1,'mc','auto','시계에서 숫자와 숫자 사이(큰 눈금 한 칸)는 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04']::text[],true,'{"seq":4,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"시계에서 숫자와 숫자 사이(큰 눈금 한 칸)는 몇 분인가요?","options":[{"t":"5분","correct":true},{"t":"1분","mis":"M2-2-u4-X02"},{"t":"10분","mis":"M2-2-u4-X04"}],"explanation":["숫자와 숫자 사이에는 작은 눈금이 5칸 있어요.","작은 눈금 한 칸은 1분이에요.","그래서 숫자와 숫자 사이는 5분이에요."],"variant_rule":{"alt":[{"stem":"시계에서 작은 눈금 한 칸은 몇 분인가요?","options":[{"t":"1분","correct":true},{"t":"5분","mis":"M2-2-u4-X02"},{"t":"10분","mis":"M2-2-u4-X04"}],"explanation":["긴바늘이 작은 눈금 한 칸을 가는 데 1분이 걸려요.","숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","그래서 작은 눈금 한 칸은 1분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#5','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C2',2,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06','M2-2-u4-X04']::text[],true,'{"seq":5,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","10 : 35는 10시 35분이에요.","시는 「열 시」, 분은 「삼십오 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"열 시 삼십오 분","correct":true},{"t":"삼십오 시 열 분","mis":"M2-2-u4-X06"},{"t":"십 시 삼십오 분","mis":"M2-2-u4-X06"},{"t":"열 시 삼십 분","mis":"M2-2-u4-X04"}],"asset":{"type":"digital","h":10,"m":35}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#6','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',2,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X02','M2-2-u4-X01','M2-2-u4-X03']::text[],true,'{"seq":6,"concept":"M2-2-u4-C1","difficulty":2,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 4와 5 사이에 있으니 4시예요.","긴바늘이 숫자 9를 가리키니 9 × 5 = 45분이에요.","그래서 4시 45분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"options":[{"t":"4시 45분","correct":true},{"t":"4시 9분","mis":"M2-2-u4-X02"},{"t":"9시 20분","mis":"M2-2-u4-X01"},{"t":"5시 45분","mis":"M2-2-u4-X03"}],"asset":{"type":"clock2","h":4,"m":45}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#7','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',2,'ox','auto','긴바늘이 숫자 3을 가리키면 3분이에요.',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":7,"concept":"M2-2-u4-C1","difficulty":2,"kind":"ox","stem":"긴바늘이 숫자 3을 가리키면 3분이에요.","answer":"X","reason_options":[{"t":"숫자 1이 5분이라 숫자 3은 3 × 5 = 15분이니까","correct":true},{"t":"긴바늘이 가리키는 숫자가 곧 분이니까","mis":"M2-2-u4-X02"}],"mis":"M2-2-u4-X02","explanation":["숫자와 숫자 사이는 5분이에요.","숫자 3까지 5분씩 3번 — 15분이에요.","그래서 3분이 아니라 15분이에요."],"variant_rule":{"alt":[{"stem":"긴바늘이 숫자 6을 가리키면 30분이에요.","answer":"O","reason_options":[{"t":"숫자 1이 5분이라 숫자 6은 6 × 5 = 30분이니까","correct":true},{"t":"긴바늘이 가리키는 숫자가 곧 분이라 6분이니까","mis":"M2-2-u4-X02"}],"explanation":["숫자와 숫자 사이는 5분이에요.","숫자 6까지 5분씩 6번 — 30분이에요.","그래서 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#8','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',2,'match','auto','긴바늘이 가리키는 숫자와 분을 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u4-C1","difficulty":2,"kind":"match","stem":"긴바늘이 가리키는 숫자와 분을 이으세요.","pairs":[{"l":"숫자 2","r":"10분"},{"l":"숫자 7","r":"35분"},{"l":"숫자 9","r":"45분"}],"mis":"M2-2-u4-X02","explanation":["긴바늘이 가리키는 숫자에 5를 곱하면 분이에요.","2 × 5 = 10, 7 × 5 = 35예요.","9 × 5 = 45예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 긴바늘이 가리키는 숫자와 분을 이으세요.","pairs":[{"l":"숫자 3","r":"15분"},{"l":"숫자 8","r":"40분"},{"l":"숫자 11","r":"55분"}],"explanation":["긴바늘이 가리키는 숫자에 5를 곱하면 분이에요.","3 × 5 = 15, 8 × 5 = 40이에요.","11 × 5 = 55예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#9','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C2',2,'mc','auto','디지털시계가 나타내는 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X06','M2-2-u4-X04']::text[],true,'{"seq":9,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"9시 5분","correct":true},{"t":"5시 9분","mis":"M2-2-u4-X06"},{"t":"9시 50분","mis":"M2-2-u4-X04"}],"explanation":["「:」 왼쪽 9는 시, 오른쪽 05는 분이에요.","05는 5분이에요.","그래서 9시 5분이에요."],"asset":{"type":"digital","h":9,"m":5},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 디지털시계가 나타내는 시각은 몇 시 몇 분인가요?","options":[{"t":"12시 40분","correct":true},{"t":"40시 12분","mis":"M2-2-u4-X06"},{"t":"12시 4분","mis":"M2-2-u4-X04"}],"explanation":["「:」 왼쪽 12는 시, 오른쪽 40은 분이에요.","시와 분을 바꾸어 읽으면 안 돼요.","그래서 12시 40분이에요."],"asset":{"type":"digital","h":12,"m":40}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_basic#10','math',2,2,'u4','L02','g2_2_math_u4_L02_basic','lesson_basic','M2-2-u4-C1',3,'error','auto','시계를 보고 친구들이 시각을 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C1","difficulty":3,"kind":"error","stem":"시계를 보고 친구들이 시각을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"연우 — 「긴바늘이 3을 가리키니까 7시 3분이야.」","correct":true,"mis_target":"M2-2-u4-X02"},{"t":"지아 — 「짧은바늘이 7과 8 사이니까 7시야.」","mis":"M2-2-u4-X16"},{"t":"세미 — 「긴바늘이 3이면 15분이라 7시 15분이야.」","mis":"M2-2-u4-X16"}],"explanation":["짧은바늘이 7과 8 사이라 7시예요.","긴바늘이 숫자 3을 가리키니 3 × 5 = 15분이에요.","연우는 숫자 3을 그대로 3분으로 읽었어요."],"asset":{"type":"clock2","h":7,"m":15},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시계를 보고 친구들이 시각을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"민수 — 「긴바늘이 8을 가리키니까 4시 8분이야.」","correct":true,"mis_target":"M2-2-u4-X02"},{"t":"하루 — 「짧은바늘이 4와 5 사이니까 4시야.」","mis":"M2-2-u4-X16"},{"t":"서아 — 「긴바늘이 8이면 40분이라 4시 40분이야.」","mis":"M2-2-u4-X16"}],"explanation":["짧은바늘이 4와 5 사이라 4시예요.","긴바늘이 숫자 8을 가리키니 8 × 5 = 40분이에요.","민수는 숫자 8을 그대로 8분으로 읽었어요."],"asset":{"type":"clock2","h":4,"m":40}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#1','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',2,'sa','auto','시계가 나타내는 시각은 11시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":2,"kind":"sa","stem":"시계가 나타내는 시각은 11시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 11과 12 사이에 있으니 11시예요.","긴바늘이 숫자 5를 가리키니 5 × 5 = 25분이에요.","그래서 11시 25분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"answer":["25"],"asset":{"type":"clock2","h":11,"m":25}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#2','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C2',2,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06','M2-2-u4-X04']::text[],true,'{"seq":2,"concept":"M2-2-u4-C2","difficulty":2,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","6 : 50은 6시 50분이에요.","시는 「여섯 시」, 분은 「오십 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"여섯 시 오십 분","correct":true},{"t":"오십 시 여섯 분","mis":"M2-2-u4-X06"},{"t":"육 시 오십 분","mis":"M2-2-u4-X06"},{"t":"여섯 시 오십오 분","mis":"M2-2-u4-X04"}],"asset":{"type":"digital","h":6,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#3','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',3,'mc','auto','지아가 일어난 시각은 7시가 조금 지났고, 긴바늘은 숫자 2를 가리켜요. 지아가 일어난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X01','M2-2-u4-X03']::text[],false,'{"seq":3,"concept":"M2-2-u4-C1","difficulty":3,"kind":"mc","stem":"지아가 일어난 시각은 7시가 조금 지났고, 긴바늘은 숫자 2를 가리켜요. 지아가 일어난 시각은 몇 시 몇 분인가요?","options":[{"t":"7시 10분","correct":true},{"t":"7시 2분","mis":"M2-2-u4-X02"},{"t":"2시 35분","mis":"M2-2-u4-X01"},{"t":"8시 10분","mis":"M2-2-u4-X03"}],"explanation":["7시가 조금 지났으니 짧은바늘은 7과 8 사이예요.","긴바늘이 숫자 2를 가리키니 2 × 5 = 10분이에요.","그래서 7시 10분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#4','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',3,'mc','auto','4시 15분을 시계에 나타낼 때 긴바늘이 가리키는 숫자는 무엇인가요?',ARRAY['M2-2-u4-X01','M2-2-u4-X02','M2-2-u4-X04']::text[],false,'{"seq":4,"concept":"M2-2-u4-C1","difficulty":3,"kind":"mc","stem":"4시 15분을 시계에 나타낼 때 긴바늘이 가리키는 숫자는 무엇인가요?","options":[{"t":"3","correct":true},{"t":"4","mis":"M2-2-u4-X01"},{"t":"15","mis":"M2-2-u4-X02"},{"t":"5","mis":"M2-2-u4-X04"}],"explanation":["15분은 5분씩 3번이에요.","5 × 3 = 15라서 긴바늘은 숫자 3을 가리켜요.","숫자 4는 짧은바늘이 가까이 있는 숫자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#5','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C2',3,'mc','auto','줄넘기를 시작한 시각이 디지털시계에 나타나 있어요. 이 시각에 긴바늘이 가리키는 숫자는 무엇인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X01','M2-2-u4-X04']::text[],false,'{"seq":5,"concept":"M2-2-u4-C2","difficulty":3,"kind":"mc","stem":"줄넘기를 시작한 시각이 디지털시계에 나타나 있어요. 이 시각에 긴바늘이 가리키는 숫자는 무엇인가요?","options":[{"t":"8","correct":true},{"t":"4","mis":"M2-2-u4-X02"},{"t":"10","mis":"M2-2-u4-X01"},{"t":"9","mis":"M2-2-u4-X04"}],"explanation":["디지털시계의 시각은 10시 40분이에요.","40분은 5분씩 8번이에요.","그래서 긴바늘은 숫자 8을 가리켜요."],"asset":{"type":"digital","h":10,"m":40}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#6','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',3,'ox','auto','2시 50분에 짧은바늘은 숫자 2를 똑바로 가리켜요.',ARRAY['M2-2-u4-X03']::text[],false,'{"seq":6,"concept":"M2-2-u4-C1","difficulty":3,"kind":"ox","stem":"2시 50분에 짧은바늘은 숫자 2를 똑바로 가리켜요.","answer":"X","reason_options":[{"t":"50분이 지나 짧은바늘은 2와 3 사이에서 3에 가까이 가 있으니까","correct":true},{"t":"몇 분이든 짧은바늘은 시의 숫자를 똑바로 가리키니까","mis":"M2-2-u4-X03"}],"mis":"M2-2-u4-X03","explanation":["짧은바늘은 분이 지나는 만큼 다음 숫자 쪽으로 조금씩 가요.","2시 50분에는 2와 3 사이, 3에 가까운 곳에 있어요.","정각일 때만 숫자를 똑바로 가리켜요."],"asset":{"type":"clock2","h":2,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#7','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',3,'mc','auto','시각이 가장 늦은 것은 어느 것인가요?',ARRAY['M2-2-u4-X04','M2-2-u4-X16','M2-2-u4-X03']::text[],false,'{"seq":7,"concept":"M2-2-u4-C1","difficulty":3,"kind":"mc","stem":"시각이 가장 늦은 것은 어느 것인가요?","options":[{"t":"3시 50분","correct":true},{"t":"3시 45분","mis":"M2-2-u4-X04"},{"t":"3시 10분","mis":"M2-2-u4-X16"},{"t":"2시 55분","mis":"M2-2-u4-X03"}],"explanation":["시가 같으면 분이 클수록 늦은 시각이에요.","2시 55분은 3시보다 이른 시각이에요.","그래서 3시 50분이 가장 늦어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#8','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',4,'essay','teacher','긴바늘이 숫자 7을 가리킬 때 몇 분인지 구하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C1","difficulty":4,"kind":"essay","stem":"긴바늘이 숫자 7을 가리킬 때 몇 분인지 구하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 숫자와 숫자 사이는 작은 눈금 5칸이라 5분이다. 숫자 7까지 5분씩 7번이므로 7 × 5 = 35분이다.","scoring_points":["숫자와 숫자 사이가 5분임을 썼는가","5씩 7번 또는 7 × 5로 셈했는가","35분이라고 구했는가"]},"explanation":["숫자와 숫자 사이는 5분이에요.","숫자 7까지는 5분씩 7번이에요.","7 × 5 = 35 — 35분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#9','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C1',4,'essay','teacher','연우는 이 시계를 보고 「7시 3분」이라고 읽었어요. 무엇이 잘못되었는지 설명하고 바른 시각을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C1","difficulty":4,"kind":"essay","stem":"연우는 이 시계를 보고 「7시 3분」이라고 읽었어요. 무엇이 잘못되었는지 설명하고 바른 시각을 써 보세요.","answer_guide":{"answer":"예: 긴바늘이 가리키는 숫자 3을 그대로 3분으로 읽었다. 숫자 3은 3 × 5 = 15분이므로 바른 시각은 7시 15분이다.","scoring_points":["숫자를 그대로 분으로 읽은 잘못을 찾았는가","3 × 5 = 15를 셈했는가","7시 15분이라고 바르게 썼는가"]},"explanation":["짧은바늘이 7과 8 사이라 7시예요.","긴바늘 숫자 3은 15분이에요.","바른 시각은 7시 15분이에요."],"asset":{"type":"clock2","h":7,"m":15}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L02_challenge#10','math',2,2,'u4','L02','g2_2_math_u4_L02_challenge','lesson_challenge','M2-2-u4-C2',4,'mc','auto','디지털시계와 같은 시각을 나타낸 바늘 시계는 어느 것인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X03','M2-2-u4-X01']::text[],false,'{"seq":10,"concept":"M2-2-u4-C2","difficulty":4,"kind":"mc","stem":"디지털시계와 같은 시각을 나타낸 바늘 시계는 어느 것인가요?","options":[{"t":"짧은바늘은 8과 9 사이, 긴바늘은 숫자 7","correct":true},{"t":"짧은바늘은 8과 9 사이, 긴바늘은 숫자 3과 4 사이","mis":"M2-2-u4-X02"},{"t":"짧은바늘은 7과 8 사이, 긴바늘은 숫자 7","mis":"M2-2-u4-X03"},{"t":"짧은바늘은 숫자 7, 긴바늘은 8과 9 사이","mis":"M2-2-u4-X01"}],"explanation":["디지털시계의 시각은 8시 35분이에요.","8시가 지났으니 짧은바늘은 8과 9 사이예요.","35분은 5 × 7 — 긴바늘은 숫자 7을 가리켜요."],"asset":{"type":"digital","h":8,"m":35}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#1','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05']::text[],true,'{"seq":1,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 1과 2 사이에 있으니 1시예요.","긴바늘이 숫자 2(10분)에서 작은 눈금 3칸 더 간 곳이니 10 + 3 = 13분이에요.","그래서 1시 13분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"1시 13분","correct":true},{"t":"1시 14분","mis":"M2-2-u4-X04"},{"t":"1시 17분","mis":"M2-2-u4-X05"}],"asset":{"type":"clock2","h":1,"m":13}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#2','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05']::text[],true,'{"seq":2,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 7과 8 사이에 있으니 7시예요.","긴바늘이 숫자 4(20분)에서 작은 눈금 2칸 더 간 곳이니 20 + 2 = 22분이에요.","그래서 7시 22분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"7시 22분","correct":true},{"t":"7시 23분","mis":"M2-2-u4-X04"},{"t":"7시 28분","mis":"M2-2-u4-X05"}],"asset":{"type":"clock2","h":7,"m":22}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#3','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',1,'mc','auto','긴바늘이 작은 눈금 3칸을 움직이면 몇 분이 지나나요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04']::text[],true,'{"seq":3,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"긴바늘이 작은 눈금 3칸을 움직이면 몇 분이 지나나요?","options":[{"t":"3분","correct":true},{"t":"15분","mis":"M2-2-u4-X02"},{"t":"30분","mis":"M2-2-u4-X04"}],"explanation":["작은 눈금 한 칸은 1분이에요.","3칸이면 1분씩 3번이에요.","그래서 3분이 지나요."],"variant_rule":{"alt":[{"stem":"긴바늘이 작은 눈금 4칸을 움직이면 몇 분이 지나나요?","options":[{"t":"4분","correct":true},{"t":"20분","mis":"M2-2-u4-X02"},{"t":"40분","mis":"M2-2-u4-X04"}],"explanation":["작은 눈금 한 칸은 1분이에요.","4칸이면 1분씩 4번이에요.","그래서 4분이 지나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#4','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',1,'sa','auto','시계가 나타내는 시각은 3시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 3시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 3과 4 사이에 있으니 3시예요.","긴바늘이 숫자 7(35분)에서 작은 눈금 4칸 더 간 곳이니 35 + 4 = 39분이에요.","그래서 3시 39분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"answer":["39"],"asset":{"type":"clock2","h":3,"m":39}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#5','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06','M2-2-u4-X04']::text[],true,'{"seq":5,"concept":"M2-2-u4-C3","difficulty":2,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","11 : 43은 11시 43분이에요.","시는 「열한 시」, 분은 「사십삼 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"열한 시 사십삼 분","correct":true},{"t":"사십삼 시 열한 분","mis":"M2-2-u4-X06"},{"t":"십일 시 사십삼 분","mis":"M2-2-u4-X06"},{"t":"열한 시 사십 분","mis":"M2-2-u4-X04"}],"asset":{"type":"digital","h":11,"m":43}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#6','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05','M2-2-u4-X03']::text[],true,'{"seq":6,"concept":"M2-2-u4-C3","difficulty":2,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 5와 6 사이에 있으니 5시예요.","긴바늘이 숫자 9(45분)에서 작은 눈금 3칸 더 간 곳이니 45 + 3 = 48분이에요.","그래서 5시 48분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"5시 48분","correct":true},{"t":"5시 49분","mis":"M2-2-u4-X04"},{"t":"5시 52분","mis":"M2-2-u4-X05"},{"t":"6시 48분","mis":"M2-2-u4-X03"}],"asset":{"type":"clock2","h":5,"m":48}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#7','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'mc','auto','긴바늘이 숫자 4(20분)에서 작은 눈금 2칸 더 간 곳을 가리켜요. 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X05','M2-2-u4-X04']::text[],true,'{"seq":7,"concept":"M2-2-u4-C3","difficulty":2,"kind":"mc","stem":"긴바늘이 숫자 4(20분)에서 작은 눈금 2칸 더 간 곳을 가리켜요. 몇 분인가요?","options":[{"t":"22분","correct":true},{"t":"42분","mis":"M2-2-u4-X02"},{"t":"18분","mis":"M2-2-u4-X05"},{"t":"24분","mis":"M2-2-u4-X04"}],"explanation":["숫자 4는 20분이에요.","2칸 더 갔으니 20 + 2 = 22예요.","그래서 22분이에요."],"variant_rule":{"alt":[{"stem":"긴바늘이 숫자 8(40분)에서 작은 눈금 1칸 덜 간 곳을 가리켜요. 몇 분인가요?","options":[{"t":"39분","correct":true},{"t":"41분","mis":"M2-2-u4-X05"},{"t":"81분","mis":"M2-2-u4-X02"},{"t":"38분","mis":"M2-2-u4-X04"}],"explanation":["숫자 8은 40분이에요.","1칸 덜 갔으니 40 − 1 = 39예요.","그래서 39분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#8','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'match','auto','긴바늘이 가리키는 같은 곳끼리 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u4-C3","difficulty":2,"kind":"match","stem":"긴바늘이 가리키는 같은 곳끼리 이으세요.","pairs":[{"l":"숫자 2에서 4칸 더 간 곳","r":"숫자 3에서 1칸 덜 간 곳"},{"l":"숫자 5에서 3칸 더 간 곳","r":"숫자 6에서 2칸 덜 간 곳"},{"l":"숫자 9에서 1칸 더 간 곳","r":"숫자 10에서 4칸 덜 간 곳"}],"mis":"M2-2-u4-X05","explanation":["숫자와 숫자 사이는 5칸이에요.","4칸 더 간 곳은 다음 숫자에서 1칸 덜 간 곳이에요.","더 간 칸과 덜 간 칸을 합하면 5칸이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 긴바늘이 가리키는 같은 곳끼리 이으세요.","pairs":[{"l":"숫자 1에서 2칸 더 간 곳","r":"숫자 2에서 3칸 덜 간 곳"},{"l":"숫자 6에서 4칸 더 간 곳","r":"숫자 7에서 1칸 덜 간 곳"},{"l":"숫자 10에서 1칸 더 간 곳","r":"숫자 11에서 4칸 덜 간 곳"}],"explanation":["숫자와 숫자 사이는 5칸이에요.","2칸 더 간 곳은 다음 숫자에서 3칸 덜 간 곳이에요.","더 간 칸과 덜 간 칸을 합하면 5칸이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#9','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',2,'ox','auto','긴바늘이 숫자 6에서 작은 눈금 2칸 더 간 곳을 가리키면 32분이에요.',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":9,"concept":"M2-2-u4-C3","difficulty":2,"kind":"ox","stem":"긴바늘이 숫자 6에서 작은 눈금 2칸 더 간 곳을 가리키면 32분이에요.","answer":"O","reason_options":[{"t":"숫자 6은 30분이고 2칸 더 갔으니 30 + 2 = 32분이니까","correct":true},{"t":"숫자 6에서 2칸이니 6 + 2 = 8분이니까","mis":"M2-2-u4-X02"}],"mis":"M2-2-u4-X02","explanation":["숫자 6은 6 × 5 = 30분이에요.","2칸 더 갔으니 2분을 더해요.","30 + 2 = 32 — 32분이에요."],"variant_rule":{"alt":[{"stem":"긴바늘이 숫자 9에서 작은 눈금 3칸 더 간 곳을 가리키면 12분이에요.","answer":"X","reason_options":[{"t":"숫자 9는 45분이라 45 + 3 = 48분이니까","correct":true},{"t":"9 + 3 = 12라서 12분이니까","mis":"M2-2-u4-X02"}],"explanation":["숫자 9는 9 × 5 = 45분이에요.","3칸 더 갔으니 3분을 더해요.","45 + 3 = 48 — 12분이 아니라 48분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_basic#10','math',2,2,'u4','L03','g2_2_math_u4_L03_basic','lesson_basic','M2-2-u4-C3',3,'error','auto','시계를 보고 친구들이 시각을 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['M2-2-u4-X04','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C3","difficulty":3,"kind":"error","stem":"시계를 보고 친구들이 시각을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"도윤 — 「긴바늘이 4 근처니까 7시 20분이야.」","correct":true,"mis_target":"M2-2-u4-X04"},{"t":"은솔 — 「숫자 4에서 2칸 더 갔으니 7시 22분이야.」","mis":"M2-2-u4-X16"},{"t":"예린 — 「짧은바늘이 7과 8 사이라 7시야.」","mis":"M2-2-u4-X16"}],"explanation":["긴바늘은 숫자 4(20분)에서 작은 눈금 2칸 더 간 곳이에요.","20 + 2 = 22라서 7시 22분이에요.","도윤이는 2칸 더 간 것을 놓쳤어요."],"asset":{"type":"clock2","h":7,"m":22},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시계를 보고 친구들이 시각을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"하루 — 「긴바늘이 8 근처니까 2시 40분이야.」","correct":true,"mis_target":"M2-2-u4-X04"},{"t":"지우 — 「숫자 8에서 2칸 덜 갔으니 2시 38분이야.」","mis":"M2-2-u4-X16"},{"t":"서아 — 「짧은바늘이 2와 3 사이라 2시야.」","mis":"M2-2-u4-X16"}],"explanation":["긴바늘은 숫자 8(40분)에서 작은 눈금 2칸 덜 간 곳이에요.","40 − 2 = 38이라서 2시 38분이에요.","하루는 2칸 덜 간 것을 놓쳤어요."],"asset":{"type":"clock2","h":2,"m":38}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#1','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',2,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X03']::text[],true,'{"seq":1,"concept":"M2-2-u4-C3","difficulty":2,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 9와 10 사이에 있으니 9시예요.","긴바늘이 숫자 11(55분)에서 작은 눈금 2칸 더 간 곳이니 55 + 2 = 57분이에요.","그래서 9시 57분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"9시 57분","correct":true},{"t":"9시 58분","mis":"M2-2-u4-X04"},{"t":"10시 57분","mis":"M2-2-u4-X03"},{"t":"9시 50분","mis":"M2-2-u4-X04"}],"asset":{"type":"clock2","h":9,"m":57}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#2','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',2,'sa','auto','시계가 나타내는 시각은 4시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u4-C3","difficulty":2,"kind":"sa","stem":"시계가 나타내는 시각은 4시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 4와 5 사이에 있으니 4시예요.","긴바늘이 숫자 5(25분)에서 작은 눈금 3칸 더 간 곳이니 25 + 3 = 28분이에요.","그래서 4시 28분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"answer":["28"],"asset":{"type":"clock2","h":4,"m":28}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#3','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'mc','auto','긴바늘이 숫자 9에서 작은 눈금 4칸 더 간 곳은 숫자 10에서 몇 칸 덜 간 곳과 같나요?',ARRAY['M2-2-u4-X05','M2-2-u4-X04','M2-2-u4-X10']::text[],false,'{"seq":3,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"긴바늘이 숫자 9에서 작은 눈금 4칸 더 간 곳은 숫자 10에서 몇 칸 덜 간 곳과 같나요?","options":[{"t":"1칸","correct":true},{"t":"4칸","mis":"M2-2-u4-X05"},{"t":"5칸","mis":"M2-2-u4-X04"},{"t":"2칸","mis":"M2-2-u4-X10"}],"explanation":["숫자와 숫자 사이는 작은 눈금 5칸이에요.","9에서 4칸 더 갔으니 10까지 1칸 남았어요.","그래서 숫자 10에서 1칸 덜 간 곳이에요 — 49분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#4','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'mc','auto','짧은바늘은 3과 4 사이, 긴바늘은 7에서 작은 눈금 2칸 더 간 곳이에요. 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X03','M2-2-u4-X05']::text[],false,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"짧은바늘은 3과 4 사이, 긴바늘은 7에서 작은 눈금 2칸 더 간 곳이에요. 몇 시 몇 분인가요?","options":[{"t":"3시 37분","correct":true},{"t":"3시 9분","mis":"M2-2-u4-X02"},{"t":"4시 37분","mis":"M2-2-u4-X03"},{"t":"3시 33분","mis":"M2-2-u4-X05"}],"explanation":["짧은바늘이 3과 4 사이라 3시예요.","숫자 7은 35분, 2칸 더 가서 37분이에요.","그래서 3시 37분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#5','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'mc','auto','디지털시계의 시각을 바늘 시계로 나타낼 때 긴바늘은 어디를 가리키나요?',ARRAY['M2-2-u4-X02','M2-2-u4-X04','M2-2-u4-X05']::text[],false,'{"seq":5,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"디지털시계의 시각을 바늘 시계로 나타낼 때 긴바늘은 어디를 가리키나요?","options":[{"t":"숫자 8에서 작은 눈금 3칸 더 간 곳","correct":true},{"t":"숫자 4와 3 사이","mis":"M2-2-u4-X02"},{"t":"숫자 9에서 작은 눈금 3칸 더 간 곳","mis":"M2-2-u4-X04"},{"t":"숫자 8에서 작은 눈금 3칸 덜 간 곳","mis":"M2-2-u4-X05"}],"explanation":["디지털시계의 시각은 11시 43분이에요.","40분은 숫자 8이고 3분이 더 있어요.","그래서 숫자 8에서 3칸 더 간 곳이에요."],"asset":{"type":"digital","h":11,"m":43}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#6','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'mc','auto','시각이 가장 이른 것은 어느 것인가요?',ARRAY['M2-2-u4-X16']::text[],false,'{"seq":6,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시각이 가장 이른 것은 어느 것인가요?","options":[{"t":"6시 48분","correct":true},{"t":"6시 52분","mis":"M2-2-u4-X16"},{"t":"7시 3분","mis":"M2-2-u4-X16"},{"t":"6시 55분","mis":"M2-2-u4-X16"}],"explanation":["시가 같으면 분이 작을수록 이른 시각이에요.","6시 48분, 6시 52분, 6시 55분, 7시 3분 차례로 늦어져요.","그래서 6시 48분이 가장 일러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#7','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',3,'ox','auto','긴바늘이 숫자 5에서 작은 눈금 4칸 더 간 곳과 숫자 6에서 작은 눈금 1칸 덜 간 곳은 같아요.',ARRAY['M2-2-u4-X05']::text[],false,'{"seq":7,"concept":"M2-2-u4-C3","difficulty":3,"kind":"ox","stem":"긴바늘이 숫자 5에서 작은 눈금 4칸 더 간 곳과 숫자 6에서 작은 눈금 1칸 덜 간 곳은 같아요.","answer":"O","reason_options":[{"t":"25 + 4 = 29, 30 − 1 = 29로 같은 곳이니까","correct":true},{"t":"더 간 곳과 덜 간 곳은 언제나 다른 곳이니까","mis":"M2-2-u4-X05"}],"mis":"M2-2-u4-X05","explanation":["숫자 5는 25분이라 4칸 더 가면 29분이에요.","숫자 6은 30분이라 1칸 덜 가면 29분이에요.","둘 다 29분 — 같은 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#8','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',4,'essay','teacher','긴바늘이 숫자 8에서 작은 눈금 1칸 덜 간 곳을 가리켜요. 몇 분인지 두 가지 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C3","difficulty":4,"kind":"essay","stem":"긴바늘이 숫자 8에서 작은 눈금 1칸 덜 간 곳을 가리켜요. 몇 분인지 두 가지 방법으로 설명해 보세요.","answer_guide":{"answer":"예: 숫자 8은 40분이고 1칸 덜 갔으니 40 − 1 = 39분이다. 숫자 7(35분)에서 4칸 더 간 곳이므로 35 + 4 = 39분이다.","scoring_points":["40 − 1로 구했는가","35 + 4로 구했는가","39분이라고 구했는가"]},"explanation":["숫자 8에서 거꾸로 1칸 — 40 − 1 = 39예요.","숫자 7에서 앞으로 4칸 — 35 + 4 = 39예요.","두 방법 모두 39분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#9','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',4,'essay','teacher','4시 28분을 시계에 나타내려고 해요. 짧은바늘과 긴바늘을 어디에 그려야 하는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C3","difficulty":4,"kind":"essay","stem":"4시 28분을 시계에 나타내려고 해요. 짧은바늘과 긴바늘을 어디에 그려야 하는지 설명해 보세요.","answer_guide":{"answer":"예: 짧은바늘은 4와 5 사이에 그린다. 28분은 숫자 5(25분)에서 3칸 더 간 곳이므로 긴바늘은 숫자 5에서 작은 눈금 3칸 더 간 곳에 그린다.","scoring_points":["짧은바늘을 4와 5 사이에 그린다고 썼는가","28분이 숫자 5에서 3칸 더 간 곳임을 썼는가","긴바늘의 자리를 바르게 썼는가"]},"explanation":["4시가 지났으니 짧은바늘은 4와 5 사이예요.","28 = 25 + 3이에요.","긴바늘은 숫자 5에서 3칸 더 간 곳이에요."],"asset":{"type":"clock2","h":4,"m":28}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L03_challenge#10','math',2,2,'u4','L03','g2_2_math_u4_L03_challenge','lesson_challenge','M2-2-u4-C3',4,'mc','auto','시각 읽기 놀이에서 지아는 2시 17분을 나타냈어요. 세미는 지아보다 긴바늘을 작은 눈금 5칸 더 돌렸어요. 세미가 나타낸 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X16','M2-2-u4-X02','M2-2-u4-X03']::text[],false,'{"seq":10,"concept":"M2-2-u4-C3","difficulty":4,"kind":"mc","stem":"시각 읽기 놀이에서 지아는 2시 17분을 나타냈어요. 세미는 지아보다 긴바늘을 작은 눈금 5칸 더 돌렸어요. 세미가 나타낸 시각은 몇 시 몇 분인가요?","options":[{"t":"2시 22분","correct":true},{"t":"2시 12분","mis":"M2-2-u4-X16"},{"t":"2시 42분","mis":"M2-2-u4-X02"},{"t":"3시 17분","mis":"M2-2-u4-X03"}],"explanation":["작은 눈금 5칸은 5분이에요.","2시 17분에서 5분이 지나면 2시 22분이에요.","긴바늘을 더 돌렸으니 시각이 늦어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#1','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',1,'mc','auto','시계가 나타내는 시각은 몇 시 몇 분 전인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":1,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"시계가 나타내는 시각은 몇 시 몇 분 전인가요?","explanation":["8시 55분에서 5분이 지나면 9시가 돼요.","그래서 8시 55분을 9시 5분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 9시예요 — 지금 시 8시가 아니에요."],"variant_rule":{"tm":{"ask":"before","form":"clock"}},"options":[{"t":"9시 5분 전","correct":true},{"t":"8시 5분 전","mis":"M2-2-u4-X07"},{"t":"9시 55분 전","mis":"M2-2-u4-X08"}],"asset":{"type":"clock2","h":8,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#2','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',1,'sa','auto','3시 50분은 4시 몇 분 전인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u4-C4","difficulty":1,"kind":"sa","stem":"3시 50분은 4시 몇 분 전인가요? 숫자로 쓰세요.","explanation":["3시 50분에서 10분이 지나면 4시가 돼요.","그래서 3시 50분을 4시 10분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 4시예요 — 지금 시 3시가 아니에요."],"variant_rule":{"tm":{"ask":"before"}},"answer":["10"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#3','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',1,'mc','auto','7시 5분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":3,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"7시 5분 전은 몇 시 몇 분인가요?","explanation":["7시 5분 전은 7시가 되기 5분 전이에요.","7시에서 긴바늘을 5분만큼 거꾸로 돌리면 6시 55분이에요.","짧은바늘은 아직 6과 7 사이에 있어서 6시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"6시 55분","correct":true},{"t":"7시 55분","mis":"M2-2-u4-X07"},{"t":"7시 5분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#4','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',1,'mc','auto','8시 55분에서 몇 분이 지나면 9시가 되나요?',ARRAY['M2-2-u4-X08','M2-2-u4-X04']::text[],true,'{"seq":4,"concept":"M2-2-u4-C4","difficulty":1,"kind":"mc","stem":"8시 55분에서 몇 분이 지나면 9시가 되나요?","options":[{"t":"5분","correct":true},{"t":"55분","mis":"M2-2-u4-X08"},{"t":"10분","mis":"M2-2-u4-X04"}],"explanation":["긴바늘이 숫자 11에서 12까지 가면 9시예요.","숫자 11에서 12까지는 5칸 — 5분이에요.","그래서 5분이 지나면 9시가 돼요."],"variant_rule":{"alt":[{"stem":"3시 50분에서 몇 분이 지나면 4시가 되나요?","options":[{"t":"10분","correct":true},{"t":"50분","mis":"M2-2-u4-X08"},{"t":"5분","mis":"M2-2-u4-X04"}],"explanation":["긴바늘이 숫자 10에서 12까지 가면 4시예요.","숫자 10에서 12까지는 10칸 — 10분이에요.","그래서 10분이 지나면 4시가 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#5','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'mc','auto','시계가 나타내는 시각은 몇 시 몇 분 전인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08','M2-2-u4-X04']::text[],true,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"시계가 나타내는 시각은 몇 시 몇 분 전인가요?","explanation":["5시 55분에서 5분이 지나면 6시가 돼요.","그래서 5시 55분을 6시 5분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 6시예요 — 지금 시 5시가 아니에요."],"variant_rule":{"tm":{"ask":"before","form":"clock"}},"options":[{"t":"6시 5분 전","correct":true},{"t":"5시 5분 전","mis":"M2-2-u4-X07"},{"t":"6시 55분 전","mis":"M2-2-u4-X08"},{"t":"6시 10분 전","mis":"M2-2-u4-X04"}],"asset":{"type":"clock2","h":5,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#6','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'mc','auto','10시 10분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":6,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"10시 10분 전은 몇 시 몇 분인가요?","explanation":["10시 10분 전은 10시가 되기 10분 전이에요.","10시에서 긴바늘을 10분만큼 거꾸로 돌리면 9시 50분이에요.","짧은바늘은 아직 9와 10 사이에 있어서 9시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"9시 50분","correct":true},{"t":"10시 50분","mis":"M2-2-u4-X07"},{"t":"10시 10분","mis":"M2-2-u4-X08"},{"t":"9시 10분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#7','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'ox','auto','10시 55분은 10시 5분 전이에요.',ARRAY['M2-2-u4-X07']::text[],true,'{"seq":7,"concept":"M2-2-u4-C4","difficulty":2,"kind":"ox","stem":"10시 55분은 10시 5분 전이에요.","answer":"X","reason_options":[{"t":"10시 55분에서 5분이 지나면 11시라서 11시 5분 전이니까","correct":true},{"t":"지금 짧은바늘이 10과 11 사이라 10시 5분 전이니까","mis":"M2-2-u4-X07"}],"mis":"M2-2-u4-X07","explanation":["10시 55분에서 5분이 지나면 11시가 돼요.","「몇 시 전」의 시는 곧 될 정각이에요.","그래서 10시 55분은 11시 5분 전이에요."],"asset":{"type":"clock2","h":10,"m":55},"variant_rule":{"alt":[{"stem":"1시 50분은 2시 10분 전이에요.","answer":"O","reason_options":[{"t":"1시 50분에서 10분이 지나면 2시가 되니까","correct":true},{"t":"1시 50분은 1시 10분 전이니까","mis":"M2-2-u4-X07"}],"explanation":["1시 50분에서 10분이 지나면 2시가 돼요.","「몇 시 전」의 시는 곧 될 정각 2시예요.","그래서 바른 말이에요."],"asset":{"type":"clock2","h":1,"m":50}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#8','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'match','auto','같은 시각끼리 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u4-C4","difficulty":2,"kind":"match","stem":"같은 시각끼리 이으세요.","pairs":[{"l":"8시 55분","r":"9시 5분 전"},{"l":"3시 50분","r":"4시 10분 전"},{"l":"6시 45분","r":"7시 15분 전"}],"mis":"M2-2-u4-X07","explanation":["8시 55분에서 5분 지나면 9시예요.","3시 50분에서 10분 지나면 4시예요.","6시 45분에서 15분 지나면 7시예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 시각끼리 이으세요.","pairs":[{"l":"11시 55분","r":"12시 5분 전"},{"l":"5시 50분","r":"6시 10분 전"},{"l":"1시 45분","r":"2시 15분 전"}],"explanation":["11시 55분에서 5분 지나면 12시예요.","5시 50분에서 10분 지나면 6시예요.","1시 45분에서 15분 지나면 2시예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#9','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',2,'sa','auto','1시 45분은 2시 몇 분 전인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":2,"kind":"sa","stem":"1시 45분은 2시 몇 분 전인가요? 숫자로 쓰세요.","explanation":["1시 45분에서 15분이 지나면 2시가 돼요.","그래서 1시 45분을 2시 15분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 2시예요 — 지금 시 1시가 아니에요."],"variant_rule":{"tm":{"ask":"before"}},"answer":["15"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_basic#10','math',2,2,'u4','L04','g2_2_math_u4_L04_basic','lesson_basic','M2-2-u4-C4',3,'error','auto','시계의 시각을 다른 방법으로 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C4","difficulty":3,"kind":"error","stem":"시계의 시각을 다른 방법으로 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하루 — 「9시 5분 전이야.」","correct":true,"mis_target":"M2-2-u4-X07"},{"t":"지우 — 「10시 5분 전이야.」","mis":"M2-2-u4-X16"},{"t":"서아 — 「5분이 지나면 10시가 돼.」","mis":"M2-2-u4-X16"}],"explanation":["시계의 시각은 9시 55분이에요.","5분이 지나면 10시가 되니 10시 5분 전이에요.","하루는 곧 될 정각이 아니라 지금 시 9시를 썼어요."],"asset":{"type":"clock2","h":9,"m":55},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시계의 시각을 다른 방법으로 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「4시 10분 전이야.」","correct":true,"mis_target":"M2-2-u4-X07"},{"t":"은솔 — 「5시 10분 전이야.」","mis":"M2-2-u4-X16"},{"t":"예린 — 「10분이 지나면 5시가 돼.」","mis":"M2-2-u4-X16"}],"explanation":["시계의 시각은 4시 50분이에요.","10분이 지나면 5시가 되니 5시 10분 전이에요.","도윤이는 곧 될 정각이 아니라 지금 시 4시를 썼어요."],"asset":{"type":"clock2","h":4,"m":50}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
