INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#3','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'mc','auto','슬기는 「8시 10분 전이야. 학교에 가려면 서둘러야지.」라고 했어요. 지금 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X08','M2-2-u4-X07']::text[],false,'{"seq":3,"concept":"M2-2-u4-C4","difficulty":3,"kind":"mc","stem":"슬기는 「8시 10분 전이야. 학교에 가려면 서둘러야지.」라고 했어요. 지금 시각은 몇 시 몇 분인가요?","options":[{"t":"7시 50분","correct":true},{"t":"8시 10분","mis":"M2-2-u4-X08"},{"t":"8시 50분","mis":"M2-2-u4-X07"},{"t":"7시 10분","mis":"M2-2-u4-X08"}],"explanation":["8시 10분 전은 8시가 되기 10분 전이에요.","8시에서 10분 거꾸로 가면 7시 50분이에요.","그래서 지금은 7시 50분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#4','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'mc','auto','「벌써 4시 55분인가?」 하고 시계를 보았어요. 이 시각을 「몇 시 몇 분 전」으로 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08','M2-2-u4-X03']::text[],false,'{"seq":4,"concept":"M2-2-u4-C4","difficulty":3,"kind":"mc","stem":"「벌써 4시 55분인가?」 하고 시계를 보았어요. 이 시각을 「몇 시 몇 분 전」으로 바르게 말한 것은 어느 것인가요?","options":[{"t":"5시 5분 전","correct":true},{"t":"4시 5분 전","mis":"M2-2-u4-X07"},{"t":"5시 55분 전","mis":"M2-2-u4-X08"},{"t":"6시 5분 전","mis":"M2-2-u4-X03"}],"explanation":["짧은바늘이 4와 5 사이라 4시 55분이에요.","5분이 지나면 5시가 돼요.","그래서 5시 5분 전이에요."],"asset":{"type":"clock2","h":4,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#5','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'mc','auto','7시 5분 전을 시계에 나타낼 때 긴바늘이 가리키는 숫자는 무엇인가요?',ARRAY['M2-2-u4-X08','M2-2-u4-X02']::text[],false,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":3,"kind":"mc","stem":"7시 5분 전을 시계에 나타낼 때 긴바늘이 가리키는 숫자는 무엇인가요?","options":[{"t":"11","correct":true},{"t":"1","mis":"M2-2-u4-X08"},{"t":"7","mis":"M2-2-u4-X02"},{"t":"5","mis":"M2-2-u4-X02"}],"explanation":["7시 5분 전은 6시 55분이에요.","55분은 5 × 11이에요.","그래서 긴바늘은 숫자 11을 가리켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#6','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'mc','auto','같은 시각끼리 바르게 짝 지은 것은 어느 것인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],false,'{"seq":6,"concept":"M2-2-u4-C4","difficulty":3,"kind":"mc","stem":"같은 시각끼리 바르게 짝 지은 것은 어느 것인가요?","options":[{"t":"2시 45분 — 3시 15분 전","correct":true},{"t":"2시 45분 — 2시 15분 전","mis":"M2-2-u4-X07"},{"t":"2시 45분 — 3시 45분 전","mis":"M2-2-u4-X08"}],"explanation":["2시 45분에서 15분이 지나면 3시예요.","그래서 2시 45분은 3시 15분 전이에요.","「전」의 시는 곧 될 정각이고, 분은 정각까지 남은 분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#7','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',3,'ox','auto','「11시 10분 전」과 「11시 10분」은 같은 시각이에요.',ARRAY['M2-2-u4-X08']::text[],false,'{"seq":7,"concept":"M2-2-u4-C4","difficulty":3,"kind":"ox","stem":"「11시 10분 전」과 「11시 10분」은 같은 시각이에요.","answer":"X","reason_options":[{"t":"11시 10분 전은 10시 50분이라 11시 10분과 다른 시각이니까","correct":true},{"t":"「전」은 붙여도 안 붙여도 같은 뜻이니까","mis":"M2-2-u4-X08"}],"mis":"M2-2-u4-X08","explanation":["11시 10분 전은 11시가 되기 10분 전 — 10시 50분이에요.","11시 10분은 11시에서 10분 지난 시각이에요.","「몇 시 몇 분 전」과 「몇 시 몇 분」은 같은 시각이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#8','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',4,'essay','teacher','5시 55분을 「몇 시 몇 분 전」으로 나타내는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C4","difficulty":4,"kind":"essay","stem":"5시 55분을 「몇 시 몇 분 전」으로 나타내는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 5시 55분에서 5분이 지나면 6시가 된다. 「몇 시 전」의 시는 곧 될 정각이므로 5시 55분은 6시 5분 전이다.","scoring_points":["5분이 지나면 6시가 됨을 썼는가","곧 될 정각 6시를 썼는가","6시 5분 전이라고 나타냈는가"]},"explanation":["정각이 되기까지 몇 분 남았는지 세어요.","5분 남았고 곧 될 정각은 6시예요.","그래서 6시 5분 전이에요."],"asset":{"type":"clock2","h":5,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#9','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',4,'essay','teacher','세미는 이 시계를 보고 「1시 10분 전」이라고 했어요. 잘못된 점을 설명하고 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":4,"kind":"essay","stem":"세미는 이 시계를 보고 「1시 10분 전」이라고 했어요. 잘못된 점을 설명하고 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 시계의 시각은 1시 50분이다. 10분이 지나면 2시가 되므로 2시 10분 전이다. 세미는 곧 될 정각이 아니라 지금 시를 썼다.","scoring_points":["시계의 시각 1시 50분을 읽었는가","곧 될 정각이 2시임을 썼는가","2시 10분 전으로 고쳤는가"]},"explanation":["시계의 시각은 1시 50분이에요.","10분이 지나면 2시예요.","그래서 2시 10분 전이에요."],"asset":{"type":"clock2","h":1,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L04_challenge#10','math',2,2,'u4','L04','g2_2_math_u4_L04_challenge','lesson_challenge','M2-2-u4-C4',4,'mc','auto','영화가 3시 10분 전에 시작해요. 지금이 2시 35분이라면 영화가 시작하기까지 몇 분 남았나요?',ARRAY['M2-2-u4-X08','M2-2-u4-X10']::text[],false,'{"seq":10,"concept":"M2-2-u4-C4","difficulty":4,"kind":"mc","stem":"영화가 3시 10분 전에 시작해요. 지금이 2시 35분이라면 영화가 시작하기까지 몇 분 남았나요?","options":[{"t":"15분","correct":true},{"t":"35분","mis":"M2-2-u4-X08"},{"t":"10분","mis":"M2-2-u4-X08"},{"t":"25분","mis":"M2-2-u4-X10"}],"explanation":["3시 10분 전은 2시 50분이에요.","2시 35분에서 2시 50분까지는 15분이에요.","「전」을 빼고 3시 10분까지 세면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#1','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',1,'mc','auto','긴바늘이 시계를 한 바퀴 도는 데 걸리는 시간은 몇 분인가요?',ARRAY['M2-2-u4-X02','M2-2-u4-X09']::text[],true,'{"seq":1,"concept":"M2-2-u4-C5","difficulty":1,"kind":"mc","stem":"긴바늘이 시계를 한 바퀴 도는 데 걸리는 시간은 몇 분인가요?","options":[{"t":"60분","correct":true},{"t":"12분","mis":"M2-2-u4-X02"},{"t":"100분","mis":"M2-2-u4-X09"}],"explanation":["긴바늘이 작은 눈금 한 칸을 가는 데 1분이 걸려요.","시계 한 바퀴에는 작은 눈금이 60칸 있어요.","그래서 한 바퀴는 60분이에요."],"variant_rule":{"alt":[{"stem":"60분은 몇 시간인가요?","options":[{"t":"1시간","correct":true},{"t":"6시간","mis":"M2-2-u4-X09"},{"t":"10시간","mis":"M2-2-u4-X09"}],"explanation":["긴바늘이 한 바퀴 도는 데 60분이 걸려요.","그동안 짧은바늘은 숫자 한 칸을 가요.","그래서 60분은 1시간이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#2','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',1,'sa','auto','책 읽기를 한 시간을 시간 띠에 나타냈어요. 책 읽기를 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"책 읽기를 한 시간을 시간 띠에 나타냈어요. 책 읽기를 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 10시 30분, 끝난 시각은 11시 30분이에요.","칠한 칸이 6칸 — 한 칸이 10분이니 60분이에요.","1시간은 60분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["60"],"asset":{"type":"tbar","from":[10,30],"to":[11,30],"label":"책 읽기를 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#3','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',1,'sa','auto','1시 30분에서 5시 30분이 될 때까지 긴바늘은 몇 바퀴 돌았나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"1시 30분에서 5시 30분이 될 때까지 긴바늘은 몇 바퀴 돌았나요? 숫자로 쓰세요.","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","1시 30분부터 5시 30분까지 4시간이 지났어요.","그래서 긴바늘은 4바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"answer":["4"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#4','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',1,'mc','auto','5시에 출발해서 6시에 도착했어요. 그동안 짧은바늘은 어떻게 움직였나요?',ARRAY['M2-2-u4-X01','M2-2-u4-X11']::text[],true,'{"seq":4,"concept":"M2-2-u4-C5","difficulty":1,"kind":"mc","stem":"5시에 출발해서 6시에 도착했어요. 그동안 짧은바늘은 어떻게 움직였나요?","options":[{"t":"5에서 6으로 숫자 한 칸 갔어요","correct":true},{"t":"한 바퀴 돌았어요","mis":"M2-2-u4-X01"},{"t":"움직이지 않았어요","mis":"M2-2-u4-X11"}],"explanation":["5시에서 6시까지는 1시간이에요.","1시간 동안 긴바늘은 한 바퀴 돌아요.","짧은바늘은 숫자 한 칸 — 5에서 6으로 가요."],"variant_rule":{"alt":[{"stem":"5시에 출발해서 6시에 도착했어요. 그동안 긴바늘은 어떻게 움직였나요?","options":[{"t":"한 바퀴 돌았어요","correct":true},{"t":"5에서 6으로 숫자 한 칸 갔어요","mis":"M2-2-u4-X01"},{"t":"숫자 12에 멈춰 있었어요","mis":"M2-2-u4-X11"}],"explanation":["5시에서 6시까지는 1시간이에요.","1시간은 60분 — 긴바늘이 한 바퀴 도는 시간이에요.","그래서 긴바늘은 한 바퀴 돌았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#5','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'sa','auto','수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C5","difficulty":2,"kind":"sa","stem":"수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 9시, 끝난 시각은 11시예요.","칠한 칸이 12칸 — 한 칸이 10분이니 120분이에요.","2시간은 60분씩 2번 — 120분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["120"],"asset":{"type":"tbar","from":[9,0],"to":[11,0],"label":"수영을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#6','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'mc','auto','2시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"2시간은 몇 분인가요?","options":[{"t":"120분","correct":true},{"t":"200분","mis":"M2-2-u4-X09"},{"t":"20분","mis":"M2-2-u4-X09"},{"t":"60분","mis":"M2-2-u4-X10"}],"explanation":["1시간은 60분이에요.","2시간은 60분이 2번이에요.","60 + 60 = 120 — 120분이에요."],"variant_rule":{"alt":[{"stem":"120분은 몇 시간인가요?","options":[{"t":"2시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X09"},{"t":"1시간","mis":"M2-2-u4-X10"},{"t":"20시간","mis":"M2-2-u4-X09"}],"explanation":["60분은 1시간이에요.","120분은 60분이 2번이에요.","그래서 2시간이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#7','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'mc','auto','3시에서 5시가 될 때까지 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":7,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"3시에서 5시가 될 때까지 긴바늘은 몇 바퀴 돌았나요?","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","3시부터 5시까지 2시간이 지났어요.","그래서 긴바늘은 2바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"options":[{"t":"2바퀴","correct":true},{"t":"5바퀴","mis":"M2-2-u4-X11"},{"t":"3바퀴","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#8','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'ox','auto','시간 띠 한 칸이 10분이면, 6칸은 1시간이에요.',ARRAY['M2-2-u4-X10']::text[],true,'{"seq":8,"concept":"M2-2-u4-C5","difficulty":2,"kind":"ox","stem":"시간 띠 한 칸이 10분이면, 6칸은 1시간이에요.","answer":"O","reason_options":[{"t":"10분씩 6칸이면 60분이고 60분은 1시간이니까","correct":true},{"t":"6칸이니 6분이니까","mis":"M2-2-u4-X10"}],"mis":"M2-2-u4-X10","explanation":["한 칸이 10분이에요.","6칸이면 10 + 10 + 10 + 10 + 10 + 10 = 60분이에요.","60분은 1시간이라 바른 말이에요."],"variant_rule":{"alt":[{"stem":"시간 띠 한 칸이 10분일 때, 8칸이 칠해져 있으면 8분이에요.","answer":"X","reason_options":[{"t":"10분씩 8칸이면 80분이니까","correct":true},{"t":"칠한 칸 수가 곧 분이니까","mis":"M2-2-u4-X10"}],"explanation":["한 칸이 10분이에요.","8칸이면 10분이 8번 — 80분이에요.","8분이 아니라 80분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#9','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',2,'mc','auto','수영을 시작한 시각과 끝난 시각이에요. 수영을 하는 데 걸린 시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":9,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"수영을 시작한 시각과 끝난 시각이에요. 수영을 하는 데 걸린 시간은 몇 분인가요?","explanation":["시작한 시각은 10시 30분, 끝난 시각은 11시 30분이에요.","10시 30분에서 긴바늘이 1바퀴 돌면 11시 30분이에요 — 1시간이에요.","1시간은 60분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"pair"}},"options":[{"t":"60분","correct":true},{"t":"100분","mis":"M2-2-u4-X09"},{"t":"70분","mis":"M2-2-u4-X10"}],"asset":{"type":"dpair","a":[10,30],"b":[11,30]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_basic#10','math',2,2,'u4','L05','g2_2_math_u4_L05_basic','lesson_basic','M2-2-u4-C5',3,'error','auto','비행기가 10시 30분에 출발해서 11시 30분에 도착했어요. 비행기를 타고 간 시간을 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C5","difficulty":3,"kind":"error","stem":"비행기가 10시 30분에 출발해서 11시 30분에 도착했어요. 비행기를 타고 간 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"곰이 — 「도착한 시각이 11시 30분이니까 90분이야.」","correct":true,"mis_target":"M2-2-u4-X11"},{"t":"펭이 — 「긴바늘이 한 바퀴 돌았으니 60분이야.」","mis":"M2-2-u4-X16"},{"t":"다예 — 「60분은 1시간이야.」","mis":"M2-2-u4-X16"}],"explanation":["10시 30분에서 11시 30분까지 긴바늘이 한 바퀴 돌았어요.","그래서 걸린 시간은 60분 — 1시간이에요.","곰이는 출발한 시각을 보지 않았어요."],"asset":{"type":"dpair","a":[10,30],"b":[11,30]},"variant_rule":{"alt":[{"stem":"공연이 9시에 시작해서 11시에 끝났어요. 공연을 본 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"곰이 — 「11시에 끝났으니까 11시간이야.」","correct":true,"mis_target":"M2-2-u4-X11"},{"t":"펭이 — 「긴바늘이 두 바퀴 돌았으니 2시간이야.」","mis":"M2-2-u4-X16"},{"t":"다예 — 「2시간은 120분이야.」","mis":"M2-2-u4-X16"}],"explanation":["9시에서 11시까지 긴바늘이 두 바퀴 돌았어요.","그래서 공연을 본 시간은 2시간 — 120분이에요.","곰이는 끝난 시각을 걸린 시간으로 말했어요."],"asset":{"type":"dpair","a":[9,0],"b":[11,0]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#1','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',2,'sa','auto','책 읽기를 한 시간을 시간 띠에 나타냈어요. 책 읽기를 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C5","difficulty":2,"kind":"sa","stem":"책 읽기를 한 시간을 시간 띠에 나타냈어요. 책 읽기를 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 2시 20분, 끝난 시각은 3시 20분이에요.","칠한 칸이 6칸 — 한 칸이 10분이니 60분이에요.","1시간은 60분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["60"],"asset":{"type":"tbar","from":[2,20],"to":[3,20],"label":"책 읽기를 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#2','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',2,'mc','auto','6시 20분에서 9시 20분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":2,"concept":"M2-2-u4-C5","difficulty":2,"kind":"mc","stem":"6시 20분에서 9시 20분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","6시 20분부터 9시 20분까지 3시간이 지났어요.","그래서 긴바늘은 3바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"options":[{"t":"3바퀴","correct":true},{"t":"9바퀴","mis":"M2-2-u4-X11"},{"t":"4바퀴","mis":"M2-2-u4-X10"},{"t":"2바퀴","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#3','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'mc','auto','멈춘 시계가 1시 30분을 가리켜요. 5시 30분으로 맞추려면 긴바늘을 몇 바퀴 돌려야 하나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X02','M2-2-u4-X10']::text[],false,'{"seq":3,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"멈춘 시계가 1시 30분을 가리켜요. 5시 30분으로 맞추려면 긴바늘을 몇 바퀴 돌려야 하나요?","options":[{"t":"4바퀴","correct":true},{"t":"5바퀴","mis":"M2-2-u4-X11"},{"t":"30바퀴","mis":"M2-2-u4-X02"},{"t":"3바퀴","mis":"M2-2-u4-X10"}],"explanation":["긴바늘이 한 바퀴 돌 때마다 1시간이 지나요.","1시 30분에서 5시 30분까지는 4시간이에요.","그래서 긴바늘을 4바퀴 돌려요."],"asset":{"type":"clock2","h":1,"m":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#4','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'mc','auto','공연이 9시에 시작해서 11시에 끝났어요. 공연을 본 시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X11','M2-2-u4-X10']::text[],false,'{"seq":4,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"공연이 9시에 시작해서 11시에 끝났어요. 공연을 본 시간은 몇 분인가요?","options":[{"t":"120분","correct":true},{"t":"200분","mis":"M2-2-u4-X09"},{"t":"11분","mis":"M2-2-u4-X11"},{"t":"60분","mis":"M2-2-u4-X10"}],"explanation":["9시에서 11시까지 긴바늘이 두 바퀴 돌았어요.","한 바퀴는 60분이에요.","60 + 60 = 120 — 120분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#5','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'mc','auto','긴바늘이 세 바퀴 도는 동안 짧은바늘은 숫자 몇 칸을 움직이나요?',ARRAY['M2-2-u4-X01','M2-2-u4-X10','M2-2-u4-X09']::text[],false,'{"seq":5,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"긴바늘이 세 바퀴 도는 동안 짧은바늘은 숫자 몇 칸을 움직이나요?","options":[{"t":"3칸","correct":true},{"t":"12칸","mis":"M2-2-u4-X01"},{"t":"1칸","mis":"M2-2-u4-X10"},{"t":"30칸","mis":"M2-2-u4-X09"}],"explanation":["긴바늘이 한 바퀴 돌면 1시간이 지나요.","1시간 동안 짧은바늘은 숫자 한 칸을 가요.","세 바퀴면 짧은바늘은 3칸을 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#6','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'mc','auto','4시 10분부터 시간 띠를 7칸 칠했어요. 한 칸이 10분이면 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"4시 10분부터 시간 띠를 7칸 칠했어요. 한 칸이 10분이면 끝난 시각은 몇 시 몇 분인가요?","options":[{"t":"5시 20분","correct":true},{"t":"4시 80분","mis":"M2-2-u4-X09"},{"t":"4시 17분","mis":"M2-2-u4-X10"},{"t":"5시 10분","mis":"M2-2-u4-X10"}],"explanation":["7칸은 10분이 7번 — 70분이에요.","70분은 1시간 10분이에요.","4시 10분에서 1시간 10분 뒤는 5시 20분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#7','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',3,'ox','auto','1시간 동안 짧은바늘은 시계를 한 바퀴 돌아요.',ARRAY['M2-2-u4-X01']::text[],false,'{"seq":7,"concept":"M2-2-u4-C5","difficulty":3,"kind":"ox","stem":"1시간 동안 짧은바늘은 시계를 한 바퀴 돌아요.","answer":"X","reason_options":[{"t":"1시간 동안 짧은바늘은 숫자 한 칸만 가고 한 바퀴는 긴바늘이 도니까","correct":true},{"t":"짧은바늘과 긴바늘은 같이 한 바퀴를 도니까","mis":"M2-2-u4-X01"}],"mis":"M2-2-u4-X01","explanation":["1시간 동안 긴바늘이 한 바퀴 돌아요.","그동안 짧은바늘은 숫자 한 칸을 가요.","짧은바늘이 한 바퀴 돌려면 12시간이 걸려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#8','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',4,'essay','teacher','자전거를 5시에 출발해서 6시에 도착했어요. 자전거를 탄 시간이 1시간이자 60분인 까닭을 시계의 두 바늘로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C5","difficulty":4,"kind":"essay","stem":"자전거를 5시에 출발해서 6시에 도착했어요. 자전거를 탄 시간이 1시간이자 60분인 까닭을 시계의 두 바늘로 설명해 보세요.","answer_guide":{"answer":"예: 긴바늘이 12에서 시작해 한 바퀴를 돌아 다시 12로 왔다. 긴바늘이 한 바퀴 도는 데 60분이 걸린다. 그동안 짧은바늘은 5에서 6으로 한 칸 가서 1시간이 지났다. 그래서 60분 = 1시간이다.","scoring_points":["긴바늘이 한 바퀴 돌았다고 썼는가","한 바퀴가 60분임을 썼는가","짧은바늘이 한 칸 가서 1시간임을 썼는가"]},"explanation":["긴바늘은 한 바퀴 — 60분이에요.","짧은바늘은 5에서 6으로 — 1시간이에요.","그래서 60분 = 1시간이에요."],"asset":{"type":"dpair","a":[5,0],"b":[6,0]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#9','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',4,'essay','teacher','민수는 이 시간 띠를 보고 「90분 걸렸어.」라고 했어요. 잘못된 점을 설명하고 걸린 시간을 바르게 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C5","difficulty":4,"kind":"essay","stem":"민수는 이 시간 띠를 보고 「90분 걸렸어.」라고 했어요. 잘못된 점을 설명하고 걸린 시간을 바르게 구해 보세요.","answer_guide":{"answer":"예: 칠한 칸은 10시 30분부터 11시 30분까지 6칸이다. 한 칸이 10분이므로 60분이다. 민수는 출발한 시각을 보지 않고 칸을 잘못 셌다.","scoring_points":["칠한 칸이 6칸임을 찾았는가","한 칸이 10분이라 60분임을 셈했는가","60분(1시간)이라고 바르게 구했는가"]},"explanation":["10시 30분부터 11시 30분까지 칠한 칸은 6칸이에요.","10분씩 6칸이면 60분이에요.","걸린 시간은 60분 — 1시간이에요."],"asset":{"type":"tbar","from":[10,30],"to":[11,30],"label":"비행기를 탄 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L05_challenge#10','math',2,2,'u4','L05','g2_2_math_u4_L05_challenge','lesson_challenge','M2-2-u4-C5',4,'mc','auto','지아는 3시 20분부터 긴바늘이 두 바퀴 도는 동안 책을 읽고, 이어서 30분 동안 그림을 그렸어요. 그림을 다 그린 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X16','M2-2-u4-X10']::text[],false,'{"seq":10,"concept":"M2-2-u4-C5","difficulty":4,"kind":"mc","stem":"지아는 3시 20분부터 긴바늘이 두 바퀴 도는 동안 책을 읽고, 이어서 30분 동안 그림을 그렸어요. 그림을 다 그린 시각은 몇 시 몇 분인가요?","options":[{"t":"5시 50분","correct":true},{"t":"5시 20분","mis":"M2-2-u4-X16"},{"t":"3시 50분","mis":"M2-2-u4-X10"},{"t":"4시 50분","mis":"M2-2-u4-X10"}],"explanation":["긴바늘이 두 바퀴 돌면 2시간 — 3시 20분에서 5시 20분이에요.","거기서 30분 더 그림을 그렸어요.","그래서 5시 50분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#1','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',1,'mc','auto','1시간 20분은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":1,"concept":"M2-2-u4-C6","difficulty":1,"kind":"mc","stem":"1시간 20분은 몇 분인가요?","explanation":["1시간은 60분이에요.","1시간 20분 = 60분 + 20분이에요.","그래서 80분이에요 — 1시간을 100분으로 보면 안 돼요."],"variant_rule":{"tm":{"ask":"h60","form":"tomin"}},"options":[{"t":"80분","correct":true},{"t":"120분","mis":"M2-2-u4-X09"},{"t":"90분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#2','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',1,'sa','auto','등산을 한 시간을 시간 띠에 나타냈어요. 등산을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u4-C6","difficulty":1,"kind":"sa","stem":"등산을 한 시간을 시간 띠에 나타냈어요. 등산을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 9시, 끝난 시각은 10시 20분이에요.","칠한 칸이 8칸 — 한 칸이 10분이니 80분이에요.","1시간 20분은 60분 + 20분 = 80분이에요."],"variant_rule":{"tm":{"ask":"elapsed","act":"등산","form":"bar"}},"answer":["80"],"asset":{"type":"tbar","from":[9,0],"to":[10,20],"label":"등산을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#3','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',1,'sa','auto','1시간 10분은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u4-C6","difficulty":1,"kind":"sa","stem":"1시간 10분은 몇 분인가요? 숫자로 쓰세요.","explanation":["1시간은 60분이에요.","1시간 10분 = 60분 + 10분이에요.","그래서 70분이에요 — 1시간을 100분으로 보면 안 돼요."],"variant_rule":{"tm":{"ask":"h60","form":"tomin"}},"answer":["70"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#4','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',1,'mc','auto','9시에 등산을 시작해서 10시 10분에 끝냈어요. 걸린 시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":4,"concept":"M2-2-u4-C6","difficulty":1,"kind":"mc","stem":"9시에 등산을 시작해서 10시 10분에 끝냈어요. 걸린 시간은 몇 분인가요?","explanation":["시작한 시각은 9시, 끝난 시각은 10시 10분이에요.","9시에서 1시간 뒤인 10시를 먼저 찾고 남은 만큼 더 세면 1시간 10분이에요.","1시간 10분은 60분 + 10분 = 70분이에요."],"variant_rule":{"tm":{"ask":"elapsed","act":"등산","form":"text"}},"options":[{"t":"70분","correct":true},{"t":"110분","mis":"M2-2-u4-X09"},{"t":"80분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#5','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'mc','auto','100분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":5,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"100분은 몇 시간 몇 분인가요?","explanation":["60분은 1시간이에요.","100분 = 60분 + 40분이에요.","60분은 1시간이니 1시간 40분이에요."],"variant_rule":{"tm":{"ask":"h60","form":"tohm"}},"options":[{"t":"1시간 40분","correct":true},{"t":"1시간","mis":"M2-2-u4-X09"},{"t":"10시간","mis":"M2-2-u4-X09"},{"t":"1시간 50분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#6','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'mc','auto','수영을 시작한 시각과 끝난 시각이에요. 수영을 하는 데 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":6,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"수영을 시작한 시각과 끝난 시각이에요. 수영을 하는 데 걸린 시간은 몇 시간 몇 분인가요?","explanation":["시작한 시각은 9시, 끝난 시각은 11시 40분이에요.","9시에서 1시간 뒤인 10시를 먼저 찾고 남은 만큼 더 세면 2시간 40분이에요.","160분 = 2시간 40분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"pair","unit":"hm"}},"options":[{"t":"2시간 40분","correct":true},{"t":"11시간 40분","mis":"M2-2-u4-X11"},{"t":"2시간 50분","mis":"M2-2-u4-X10"},{"t":"2시간 30분","mis":"M2-2-u4-X10"}],"asset":{"type":"dpair","a":[9,0],"b":[11,40]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#7','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'sa','auto','수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u4-C6","difficulty":2,"kind":"sa","stem":"수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 1시 30분, 끝난 시각은 3시예요.","칠한 칸이 9칸 — 한 칸이 10분이니 90분이에요.","1시간 30분은 60분 + 30분 = 90분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["90"],"asset":{"type":"tbar","from":[1,30],"to":[3,0],"label":"수영을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#8','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'match','auto','같은 시간끼리 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u4-C6","difficulty":2,"kind":"match","stem":"같은 시간끼리 이으세요.","pairs":[{"l":"1시간 10분","r":"70분"},{"l":"1시간 40분","r":"100분"},{"l":"2시간 20분","r":"140분"}],"mis":"M2-2-u4-X09","explanation":["1시간은 60분이에요.","1시간 10분 = 60 + 10 = 70분, 1시간 40분 = 60 + 40 = 100분이에요.","2시간 20분 = 120 + 20 = 140분이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 시간끼리 이으세요.","pairs":[{"l":"1시간 30분","r":"90분"},{"l":"2시간","r":"120분"},{"l":"1시간 50분","r":"110분"}],"explanation":["1시간은 60분이에요.","1시간 30분 = 60 + 30 = 90분, 2시간 = 60 + 60 = 120분이에요.","1시간 50분 = 60 + 50 = 110분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#9','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',2,'ox','auto','1시간 10분은 110분이에요.',ARRAY['M2-2-u4-X09']::text[],true,'{"seq":9,"concept":"M2-2-u4-C6","difficulty":2,"kind":"ox","stem":"1시간 10분은 110분이에요.","answer":"X","reason_options":[{"t":"1시간은 60분이라 1시간 10분은 60 + 10 = 70분이니까","correct":true},{"t":"1과 10을 이어 쓰면 110이니까","mis":"M2-2-u4-X09"}],"mis":"M2-2-u4-X09","explanation":["1시간은 100분이 아니라 60분이에요.","1시간 10분 = 60분 + 10분이에요.","그래서 70분이에요."],"variant_rule":{"alt":[{"stem":"1시간 50분은 110분이에요.","answer":"O","reason_options":[{"t":"1시간은 60분이라 1시간 50분은 60 + 50 = 110분이니까","correct":true},{"t":"1시간은 100분이라 150분이니까","mis":"M2-2-u4-X09"}],"explanation":["1시간은 60분이에요.","1시간 50분 = 60분 + 50분이에요.","그래서 110분 — 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_basic#10','math',2,2,'u4','L06','g2_2_math_u4_L06_basic','lesson_basic','M2-2-u4-C6',3,'error','auto','체험학습에서 열매 줍기를 한 시각이에요. 걸린 시간을 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":3,"kind":"error","stem":"체험학습에서 열매 줍기를 한 시각이에요. 걸린 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「1시간 10분이니까 110분이야.」","correct":true,"mis_target":"M2-2-u4-X09"},{"t":"서아 — 「9시 30분에서 1시간 뒤 10시 30분, 10분 더 가서 1시간 10분이야.」","mis":"M2-2-u4-X16"},{"t":"하루 — 「60분과 10분을 합해 70분이야.」","mis":"M2-2-u4-X16"}],"explanation":["9시 30분부터 10시 40분까지는 1시간 10분이에요.","1시간 10분 = 60분 + 10분 = 70분이에요.","지우는 1시간을 100분으로 보았어요."],"asset":{"type":"dpair","a":[9,30],"b":[10,40]},"variant_rule":{"alt":[{"stem":"체험학습에서 음식을 만들어 먹은 시각이에요. 걸린 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「1시간 20분이니까 120분이야.」","correct":true,"mis_target":"M2-2-u4-X09"},{"t":"은솔 — 「10시 40분에서 1시간 뒤 11시 40분, 20분 더 가서 1시간 20분이야.」","mis":"M2-2-u4-X16"},{"t":"예린 — 「60분과 20분을 합해 80분이야.」","mis":"M2-2-u4-X16"}],"explanation":["10시 40분부터 12시까지는 1시간 20분이에요.","1시간 20분 = 60분 + 20분 = 80분이에요.","도윤이는 1시간을 100분으로 보았어요."],"asset":{"type":"dpair","a":[10,40],"b":[12,0]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#1','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',2,'mc','auto','130분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":1,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"130분은 몇 시간 몇 분인가요?","explanation":["60분은 1시간이에요.","130분 = 120분 + 10분이에요.","120분은 2시간이니 2시간 10분이에요."],"variant_rule":{"tm":{"ask":"h60","form":"tohm"}},"options":[{"t":"2시간 10분","correct":true},{"t":"1시간 30분","mis":"M2-2-u4-X09"},{"t":"13시간","mis":"M2-2-u4-X09"},{"t":"2시간 20분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#2','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',2,'mc','auto','10시 40분에 책 읽기를 시작해서 12시에 끝냈어요. 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":2,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"10시 40분에 책 읽기를 시작해서 12시에 끝냈어요. 걸린 시간은 몇 시간 몇 분인가요?","explanation":["시작한 시각은 10시 40분, 끝난 시각은 12시예요.","10시 40분에서 1시간 뒤인 11시 40분을 먼저 찾고 남은 만큼 더 세면 1시간 20분이에요.","80분 = 1시간 20분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"text","unit":"hm"}},"options":[{"t":"1시간 20분","correct":true},{"t":"12시간","mis":"M2-2-u4-X11"},{"t":"1시간 30분","mis":"M2-2-u4-X10"},{"t":"1시간 10분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#3','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'mc','auto','2시 40분에 책 읽기를 시작해서 1시간 30분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":3,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"2시 40분에 책 읽기를 시작해서 1시간 30분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","explanation":["시작한 시각 2시 40분에서 1시간 30분이 지난 시각을 찾아요.","1시간 뒤는 3시 40분, 거기서 30분 더 지나면 4시 10분이에요.","분이 60분이 되면 시가 하나 커져요."],"variant_rule":{"tm":{"ask":"after"}},"options":[{"t":"4시 10분","correct":true},{"t":"3시 70분","mis":"M2-2-u4-X09"},{"t":"4시 20분","mis":"M2-2-u4-X10"},{"t":"4시","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#4','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'mc','auto','서울에서 9시에 출발한 기차가 부산에 11시 40분에 도착했어요. 걸린 시간은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":4,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"서울에서 9시에 출발한 기차가 부산에 11시 40분에 도착했어요. 걸린 시간은 몇 분인가요?","options":[{"t":"160분","correct":true},{"t":"240분","mis":"M2-2-u4-X09"},{"t":"140분","mis":"M2-2-u4-X10"},{"t":"100분","mis":"M2-2-u4-X10"}],"explanation":["9시에서 긴바늘이 두 바퀴 돌면 11시 — 2시간이에요.","거기서 40분 더 가서 2시간 40분이에요.","120 + 40 = 160 — 160분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#5','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'mc','auto','체험학습에서 「음식 만들어 먹기」를 10시 40분부터 12시까지 했어요. 걸린 시간은 얼마인가요?',ARRAY['M2-2-u4-X10','M2-2-u4-X09','M2-2-u4-X11']::text[],false,'{"seq":5,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"체험학습에서 「음식 만들어 먹기」를 10시 40분부터 12시까지 했어요. 걸린 시간은 얼마인가요?","options":[{"t":"1시간 20분","correct":true},{"t":"2시간","mis":"M2-2-u4-X10"},{"t":"1시간 60분","mis":"M2-2-u4-X09"},{"t":"12시간","mis":"M2-2-u4-X11"}],"explanation":["10시 40분에서 1시간 뒤는 11시 40분이에요.","11시 40분에서 12시까지 20분 더 갔어요.","그래서 1시간 20분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#6','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'mc','auto','하루에 30분씩 운동해요. 4일 동안 운동한 시간은 모두 몇 시간인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":6,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"하루에 30분씩 운동해요. 4일 동안 운동한 시간은 모두 몇 시간인가요?","options":[{"t":"2시간","correct":true},{"t":"1시간 20분","mis":"M2-2-u4-X09"},{"t":"4시간","mis":"M2-2-u4-X10"},{"t":"3시간","mis":"M2-2-u4-X10"}],"explanation":["30분씩 4번이면 120분이에요.","60분이 1시간이라 120분은 2시간이에요.","1시간을 100분으로 보면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#7','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',3,'ox','auto','2시 30분부터 4시까지는 1시간 30분이에요.',ARRAY['M2-2-u4-X10']::text[],false,'{"seq":7,"concept":"M2-2-u4-C6","difficulty":3,"kind":"ox","stem":"2시 30분부터 4시까지는 1시간 30분이에요.","answer":"O","reason_options":[{"t":"2시 30분에서 1시간 뒤가 3시 30분이고 30분 더 가면 4시라서 1시간 30분이니까","correct":true},{"t":"4 − 2 = 2라서 2시간이니까","mis":"M2-2-u4-X10"}],"mis":"M2-2-u4-X10","explanation":["2시 30분에서 1시간 뒤는 3시 30분이에요.","3시 30분에서 4시까지 30분이에요.","그래서 1시간 30분 — 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#8','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',4,'essay','teacher','9시에 등산을 시작해서 10시 20분에 산 정상에 도착했어요. 걸린 시간을 「몇 시간 몇 분」과 「몇 분」으로 나타내고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C6","difficulty":4,"kind":"essay","stem":"9시에 등산을 시작해서 10시 20분에 산 정상에 도착했어요. 걸린 시간을 「몇 시간 몇 분」과 「몇 분」으로 나타내고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 9시에서 1시간 뒤는 10시이고 20분 더 갔으므로 1시간 20분이다. 1시간은 60분이라 60 + 20 = 80분이다.","scoring_points":["1시간을 먼저 찾고 남은 만큼 세었는가","1시간 20분이라고 구했는가","80분으로 바꾸었는가"]},"explanation":["1시간을 먼저 — 9시에서 10시까지예요.","20분 더 갔으니 1시간 20분이에요.","60분 + 20분 = 80분이에요."],"asset":{"type":"tbar","from":[9,0],"to":[10,20],"label":"등산한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#9','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',4,'essay','teacher','「1시간 10분」을 110분이라고 한 친구가 있어요. 잘못된 점을 설명하고 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C6","difficulty":4,"kind":"essay","stem":"「1시간 10분」을 110분이라고 한 친구가 있어요. 잘못된 점을 설명하고 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 1시간을 100분으로 생각해서 110분이라고 했다. 1시간은 60분이므로 1시간 10분은 60 + 10 = 70분이다.","scoring_points":["1시간을 100분으로 본 잘못을 찾았는가","1시간 = 60분을 썼는가","70분이라고 고쳤는가"]},"explanation":["1시간은 60분이에요.","1시간 10분 = 60분 + 10분이에요.","바른 답은 70분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L06_challenge#10','math',2,2,'u4','L06','g2_2_math_u4_L06_challenge','lesson_challenge','M2-2-u4-C6',4,'mc','auto','열매 줍기(9시 30분~10시 40분)와 자연물로 작품 만들기(12시~12시 40분)를 했어요. 두 활동에 걸린 시간은 모두 몇 분인가요?',ARRAY['M2-2-u4-X16','M2-2-u4-X09','M2-2-u4-X10']::text[],false,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":4,"kind":"mc","stem":"열매 줍기(9시 30분~10시 40분)와 자연물로 작품 만들기(12시~12시 40분)를 했어요. 두 활동에 걸린 시간은 모두 몇 분인가요?","options":[{"t":"110분","correct":true},{"t":"70분","mis":"M2-2-u4-X16"},{"t":"150분","mis":"M2-2-u4-X09"},{"t":"100분","mis":"M2-2-u4-X10"}],"explanation":["열매 줍기는 1시간 10분 — 70분이에요.","작품 만들기는 40분이에요.","70 + 40 = 110 — 110분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#1','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',1,'mc','auto','하루는 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X09']::text[],true,'{"seq":1,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"하루는 몇 시간인가요?","options":[{"t":"24시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X13"},{"t":"60시간","mis":"M2-2-u4-X09"}],"explanation":["짧은바늘이 한 바퀴 돌면 12시간이에요.","하루 동안 짧은바늘은 두 바퀴 돌아요.","12 + 12 = 24 — 하루는 24시간이에요."],"variant_rule":{"alt":[{"stem":"짧은바늘이 두 바퀴 돌면 몇 시간이 지나나요?","options":[{"t":"24시간","correct":true},{"t":"2시간","mis":"M2-2-u4-X01"},{"t":"12시간","mis":"M2-2-u4-X13"}],"explanation":["짧은바늘이 한 바퀴 돌면 12시간이에요.","두 바퀴면 12시간이 2번이에요.","그래서 24시간 — 하루예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#2','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',1,'mc','auto','밤 12시부터 낮 12시까지를 무엇이라고 하나요?',ARRAY['M2-2-u4-X12','M2-2-u4-X13']::text[],true,'{"seq":2,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"밤 12시부터 낮 12시까지를 무엇이라고 하나요?","options":[{"t":"오전","correct":true},{"t":"오후","mis":"M2-2-u4-X12"},{"t":"하루","mis":"M2-2-u4-X13"}],"explanation":["하루는 낮 12시에서 둘로 나뉘어요.","밤 12시부터 낮 12시까지가 오전이에요.","낮 12시부터 밤 12시까지가 오후예요."],"variant_rule":{"alt":[{"stem":"낮 12시부터 밤 12시까지를 무엇이라고 하나요?","options":[{"t":"오후","correct":true},{"t":"오전","mis":"M2-2-u4-X12"},{"t":"정각","mis":"M2-2-u4-X11"}],"explanation":["하루는 낮 12시에서 둘로 나뉘어요.","밤 12시부터 낮 12시까지가 오전이에요.","낮 12시부터 밤 12시까지가 오후예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#3','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',1,'sa','auto','1일 5시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u4-C7","difficulty":1,"kind":"sa","stem":"1일 5시간은 몇 시간인가요? 숫자로 쓰세요.","explanation":["하루는 24시간이에요 — 짧은바늘이 두 바퀴 돌아요.","1일 5시간 = 24시간 + 5시간이에요.","그래서 29시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"toh"}},"answer":["29"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#4','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',1,'mc','auto','오전 11시에 수영을 시작해서 2시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":4,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"오전 11시에 수영을 시작해서 2시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 11시에서 1시간 뒤가 낮 12시, 거기서 1시간 더 가면 오후 1시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 1시","correct":true},{"t":"오전 1시","mis":"M2-2-u4-X12"},{"t":"오후 13시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#5','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'mc','auto','30시간은 며칠 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X10']::text[],true,'{"seq":5,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"30시간은 며칠 몇 시간인가요?","explanation":["24시간은 1일이에요.","30시간 = 24시간 + 6시간이에요.","그래서 1일 6시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"tod"}},"options":[{"t":"1일 6시간","correct":true},{"t":"2일 6시간","mis":"M2-2-u4-X13"},{"t":"3일","mis":"M2-2-u4-X13"},{"t":"1일 7시간","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#6','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'mc','auto','세미의 생활 계획표예요. 박물관 관람은 몇 시간 동안 했나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":6,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"세미의 생활 계획표예요. 박물관 관람은 몇 시간 동안 했나요?","options":[{"t":"5시간","correct":true},{"t":"17시간","mis":"M2-2-u4-X11"},{"t":"12시간","mis":"M2-2-u4-X11"},{"t":"4시간","mis":"M2-2-u4-X10"}],"explanation":["박물관 관람은 낮 12시에 시작해서 오후 5시에 끝났어요.","낮 12시에서 오후 5시까지 칸을 세면 5칸이에요.","그래서 5시간이에요."],"asset":{"type":"dbar","acts":[["잠",0,7,"😴"],["아침 식사",7,8,"🍚"],["블록 놀이",8,11,"🧱"],["점심 식사",11,12,"🍜"],["박물관 관람",12,17,"🖼️"],["저녁 식사",17,18,"🍲"],["독서",18,21,"📖"],["잠",21,24,"😴"]]},"variant_rule":{"alt":[{"stem":"세미의 생활 계획표예요. 블록 놀이는 몇 시간 동안 했나요?","options":[{"t":"3시간","correct":true},{"t":"11시간","mis":"M2-2-u4-X11"},{"t":"8시간","mis":"M2-2-u4-X11"},{"t":"2시간","mis":"M2-2-u4-X10"}],"explanation":["블록 놀이는 오전 8시에 시작해서 오전 11시에 끝났어요.","오전 8시에서 11시까지 칸을 세면 3칸이에요.","그래서 3시간이에요."],"asset":{"type":"dbar","acts":[["잠",0,7,"😴"],["아침 식사",7,8,"🍚"],["블록 놀이",8,11,"🧱"],["점심 식사",11,12,"🍜"],["박물관 관람",12,17,"🖼️"],["저녁 식사",17,18,"🍲"],["독서",18,21,"📖"],["잠",21,24,"😴"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#7','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'mc','auto','세미의 생활 계획표에서 오전에 한 일이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u4-X16']::text[],true,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"세미의 생활 계획표에서 오전에 한 일이 아닌 것은 어느 것인가요?","options":[{"t":"박물관 관람","correct":true},{"t":"아침 식사","mis":"M2-2-u4-X16"},{"t":"블록 놀이","mis":"M2-2-u4-X16"}],"explanation":["오전은 밤 12시부터 낮 12시까지예요.","아침 식사·블록 놀이·점심 식사는 낮 12시 전에 했어요.","박물관 관람은 낮 12시부터라 오후에 한 일이에요."],"asset":{"type":"dbar","acts":[["잠",0,7,"😴"],["아침 식사",7,8,"🍚"],["블록 놀이",8,11,"🧱"],["점심 식사",11,12,"🍜"],["박물관 관람",12,17,"🖼️"],["저녁 식사",17,18,"🍲"],["독서",18,21,"📖"],["잠",21,24,"😴"]]},"variant_rule":{"alt":[{"stem":"세미의 생활 계획표에서 오후에 한 일이 아닌 것은 어느 것인가요?","options":[{"t":"블록 놀이","correct":true},{"t":"저녁 식사","mis":"M2-2-u4-X16"},{"t":"독서","mis":"M2-2-u4-X16"}],"explanation":["오후는 낮 12시부터 밤 12시까지예요.","저녁 식사·독서는 낮 12시가 지나서 했어요.","블록 놀이는 오전 8시부터 11시까지라 오전에 한 일이에요."],"asset":{"type":"dbar","acts":[["잠",0,7,"😴"],["아침 식사",7,8,"🍚"],["블록 놀이",8,11,"🧱"],["점심 식사",11,12,"🍜"],["박물관 관람",12,17,"🖼️"],["저녁 식사",17,18,"🍲"],["독서",18,21,"📖"],["잠",21,24,"😴"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#8','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'ox','auto','오후에 하는 일이 많으면 오후가 오전보다 더 길어요.',ARRAY['M2-2-u4-X13']::text[],true,'{"seq":8,"concept":"M2-2-u4-C7","difficulty":2,"kind":"ox","stem":"오후에 하는 일이 많으면 오후가 오전보다 더 길어요.","answer":"X","reason_options":[{"t":"오전도 12시간, 오후도 12시간으로 길이가 같으니까","correct":true},{"t":"하는 일이 많을수록 시간이 길어지니까","mis":"M2-2-u4-X13"}],"mis":"M2-2-u4-X13","explanation":["오전은 밤 12시부터 낮 12시까지 12시간이에요.","오후는 낮 12시부터 밤 12시까지 12시간이에요.","하는 일이 많아도 시간의 길이는 같아요."],"variant_rule":{"alt":[{"stem":"오전과 오후는 각각 12시간이에요.","answer":"O","reason_options":[{"t":"짧은바늘이 한 바퀴 도는 12시간씩으로 나뉘니까","correct":true},{"t":"오후가 오전보다 하는 일이 많아서 더 기니까","mis":"M2-2-u4-X13"}],"explanation":["오전은 짧은바늘이 한 바퀴 — 12시간이에요.","오후도 짧은바늘이 한 바퀴 — 12시간이에요.","그래서 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#9','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',2,'mc','auto','오전 10시에 수영을 시작해서 4시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":9,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 10시에 수영을 시작해서 4시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 10시에서 2시간 뒤가 낮 12시, 거기서 2시간 더 가면 오후 2시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 2시","correct":true},{"t":"오전 2시","mis":"M2-2-u4-X12"},{"t":"오후 14시","mis":"M2-2-u4-X12"},{"t":"오전 14시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_basic#10','math',2,2,'u4','L07','g2_2_math_u4_L07_basic','lesson_basic','M2-2-u4-C7',3,'error','auto','어제 오전 9시에 여행을 떠나 오늘 오전 11시에 돌아왔어요. 여행한 시간을 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C7","difficulty":3,"kind":"error","stem":"어제 오전 9시에 여행을 떠나 오늘 오전 11시에 돌아왔어요. 여행한 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"펭이 — 「9시부터 11시까지니까 2시간이야.」","correct":true,"mis_target":"M2-2-u4-X13"},{"t":"곰이 — 「하루 지나 오늘 오전 9시, 2시간 더 가서 26시간이야.」","mis":"M2-2-u4-X16"},{"t":"다예 — 「1일 2시간이라고도 해.」","mis":"M2-2-u4-X16"}],"explanation":["어제 오전 9시에서 하루(24시간)가 지나면 오늘 오전 9시예요.","거기서 2시간 더 가면 오늘 오전 11시예요.","24 + 2 = 26시간 — 펭이는 하루를 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"어제 오전 8시에 여행을 떠나 오늘 오전 11시에 돌아왔어요. 여행한 시간을 잘못 말한 친구는 누구인가요?","options":[{"t":"펭이 — 「8시부터 11시까지니까 3시간이야.」","correct":true,"mis_target":"M2-2-u4-X13"},{"t":"곰이 — 「하루 지나 오늘 오전 8시, 3시간 더 가서 27시간이야.」","mis":"M2-2-u4-X16"},{"t":"다예 — 「1일 3시간이라고도 해.」","mis":"M2-2-u4-X16"}],"explanation":["어제 오전 8시에서 하루(24시간)가 지나면 오늘 오전 8시예요.","거기서 3시간 더 가면 오늘 오전 11시예요.","24 + 3 = 27시간 — 펭이는 하루를 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#1','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',2,'sa','auto','2일은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"2일은 몇 시간인가요? 숫자로 쓰세요.","explanation":["하루는 24시간이에요 — 짧은바늘이 두 바퀴 돌아요.","2일은 24시간이 2번 — 48시간이에요.","그래서 48시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"toh"}},"answer":["48"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#2','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',2,'mc','auto','오전 9시에 책 읽기를 시작해서 5시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":2,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 9시에 책 읽기를 시작해서 5시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 9시에서 3시간 뒤가 낮 12시, 거기서 2시간 더 가면 오후 2시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 2시","correct":true},{"t":"오전 2시","mis":"M2-2-u4-X12"},{"t":"오후 14시","mis":"M2-2-u4-X12"},{"t":"오전 14시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#3','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'mc','auto','오전 10시 30분에 박물관에 들어가 3시간 동안 관람했어요. 박물관에서 나온 시각은 언제인가요?',ARRAY['M2-2-u4-X12','M2-2-u4-X10']::text[],false,'{"seq":3,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"오전 10시 30분에 박물관에 들어가 3시간 동안 관람했어요. 박물관에서 나온 시각은 언제인가요?","options":[{"t":"오후 1시 30분","correct":true},{"t":"오전 1시 30분","mis":"M2-2-u4-X12"},{"t":"오후 13시 30분","mis":"M2-2-u4-X12"},{"t":"오후 2시 30분","mis":"M2-2-u4-X10"}],"explanation":["오전 10시 30분에서 1시간 30분 뒤가 낮 12시예요.","거기서 1시간 30분 더 가면 오후 1시 30분이에요.","낮 12시를 지나면 오후 1시부터 다시 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#4','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'mc','auto','하루 동안 짧은바늘과 긴바늘은 각각 몇 바퀴 도나요?',ARRAY['M2-2-u4-X13','M2-2-u4-X01','M2-2-u4-X09']::text[],false,'{"seq":4,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"하루 동안 짧은바늘과 긴바늘은 각각 몇 바퀴 도나요?","options":[{"t":"짧은바늘 2바퀴, 긴바늘 24바퀴","correct":true},{"t":"짧은바늘 1바퀴, 긴바늘 12바퀴","mis":"M2-2-u4-X13"},{"t":"짧은바늘 24바퀴, 긴바늘 2바퀴","mis":"M2-2-u4-X01"},{"t":"짧은바늘 2바퀴, 긴바늘 60바퀴","mis":"M2-2-u4-X09"}],"explanation":["짧은바늘은 12시간에 한 바퀴 — 하루에 2바퀴예요.","긴바늘은 1시간에 한 바퀴 — 하루 24시간에 24바퀴예요.","하루는 24시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#5','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'mc','auto','세미의 생활 계획표에서 하는 일에 걸린 시간을 모두 더하면 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X10']::text[],false,'{"seq":5,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"세미의 생활 계획표에서 하는 일에 걸린 시간을 모두 더하면 몇 시간인가요?","options":[{"t":"24시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X13"},{"t":"7시간","mis":"M2-2-u4-X10"},{"t":"20시간","mis":"M2-2-u4-X10"}],"explanation":["잠 10시간, 아침 1, 블록 3, 점심 1, 박물관 5, 저녁 1, 독서 3시간이에요.","10 + 1 + 3 + 1 + 5 + 1 + 3 = 24예요.","하루를 모두 칠했으니 24시간 — 하루예요."],"asset":{"type":"dbar","acts":[["잠",0,7,"😴"],["아침 식사",7,8,"🍚"],["블록 놀이",8,11,"🧱"],["점심 식사",11,12,"🍜"],["박물관 관람",12,17,"🖼️"],["저녁 식사",17,18,"🍲"],["독서",18,21,"📖"],["잠",21,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#6','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'mc','auto','오후 3시는 낮 12시에서 몇 시간 뒤인가요?',ARRAY['M2-2-u4-X12','M2-2-u4-X13']::text[],false,'{"seq":6,"concept":"M2-2-u4-C7","difficulty":3,"kind":"mc","stem":"오후 3시는 낮 12시에서 몇 시간 뒤인가요?","options":[{"t":"3시간","correct":true},{"t":"15시간","mis":"M2-2-u4-X12"},{"t":"9시간","mis":"M2-2-u4-X12"},{"t":"12시간","mis":"M2-2-u4-X13"}],"explanation":["낮 12시 다음이 오후 1시예요.","오후 1시, 2시, 3시 — 3시간 뒤예요.","오후의 시는 낮 12시에서 다시 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#7','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',3,'ox','auto','오전 9시부터 오후 2시까지는 5시간이에요.',ARRAY['M2-2-u4-X12']::text[],false,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":3,"kind":"ox","stem":"오전 9시부터 오후 2시까지는 5시간이에요.","answer":"O","reason_options":[{"t":"오전 9시에서 3시간 뒤가 낮 12시이고 2시간 더 가면 오후 2시라서 5시간이니까","correct":true},{"t":"9 − 2 = 7이라서 7시간이니까","mis":"M2-2-u4-X12"}],"mis":"M2-2-u4-X12","explanation":["오전 9시에서 낮 12시까지 3시간이에요.","낮 12시에서 오후 2시까지 2시간이에요.","3 + 2 = 5 — 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#8','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',4,'essay','teacher','어제 오전 9시에 여행을 떠나 오늘 오전 11시에 돌아왔어요. 여행한 시간은 몇 시간인지 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C7","difficulty":4,"kind":"essay","stem":"어제 오전 9시에 여행을 떠나 오늘 오전 11시에 돌아왔어요. 여행한 시간은 몇 시간인지 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 어제 오전 9시에서 하루가 지나면 오늘 오전 9시이고 하루는 24시간이다. 오늘 오전 9시에서 11시까지 2시간 더 갔다. 24 + 2 = 26시간이다.","scoring_points":["하루(24시간)가 지났음을 썼는가","2시간을 더 셈했는가","26시간(1일 2시간)이라고 구했는가"]},"explanation":["하루가 지나면 같은 시각이 돼요 — 24시간이에요.","거기서 2시간 더 갔어요.","24 + 2 = 26시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#9','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',4,'essay','teacher','세미는 오후에 하는 일이 더 많아서 「오후가 오전보다 길어.」라고 했어요. 세미의 말이 맞는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C7","difficulty":4,"kind":"essay","stem":"세미는 오후에 하는 일이 더 많아서 「오후가 오전보다 길어.」라고 했어요. 세미의 말이 맞는지 설명해 보세요.","answer_guide":{"answer":"예: 맞지 않다. 오전은 밤 12시부터 낮 12시까지 12시간이고, 오후도 낮 12시부터 밤 12시까지 12시간이다. 하는 일이 많아도 시간의 길이는 같다.","scoring_points":["세미의 말이 맞지 않다고 했는가","오전·오후가 각각 12시간임을 썼는가","하는 일의 수와 시간의 길이는 다르다고 썼는가"]},"explanation":["오전은 12시간이에요.","오후도 12시간이에요.","하는 일이 많다고 시간이 길어지지 않아요."],"asset":{"type":"dbar","acts":[["잠",0,7,"😴"],["아침 식사",7,8,"🍚"],["블록 놀이",8,11,"🧱"],["점심 식사",11,12,"🍜"],["박물관 관람",12,17,"🖼️"],["저녁 식사",17,18,"🍲"],["독서",18,21,"📖"],["잠",21,24,"😴"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L07_challenge#10','math',2,2,'u4','L07','g2_2_math_u4_L07_challenge','lesson_challenge','M2-2-u4-C7',4,'mc','auto','오후 9시에 잠들어 다음 날 오전 7시에 일어났어요. 잠잔 시간은 몇 시간인가요?',ARRAY['M2-2-u4-X12','M2-2-u4-X10']::text[],false,'{"seq":10,"concept":"M2-2-u4-C7","difficulty":4,"kind":"mc","stem":"오후 9시에 잠들어 다음 날 오전 7시에 일어났어요. 잠잔 시간은 몇 시간인가요?","options":[{"t":"10시간","correct":true},{"t":"2시간","mis":"M2-2-u4-X12"},{"t":"16시간","mis":"M2-2-u4-X12"},{"t":"14시간","mis":"M2-2-u4-X10"}],"explanation":["오후 9시에서 밤 12시까지 3시간이에요.","밤 12시에서 오전 7시까지 7시간이에요.","3 + 7 = 10 — 10시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#1','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',1,'mc','auto','1주일은 며칠인가요?',ARRAY['M2-2-u4-X15']::text[],true,'{"seq":1,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"1주일은 며칠인가요?","options":[{"t":"7일","correct":true},{"t":"5일","mis":"M2-2-u4-X15"},{"t":"10일","mis":"M2-2-u4-X15"}],"explanation":["일요일부터 토요일까지가 1주일이에요.","일, 월, 화, 수, 목, 금, 토 — 7일이에요.","달력의 한 줄도 7칸이에요."],"variant_rule":{"alt":[{"stem":"달력에서 한 줄(일요일부터 토요일까지)은 며칠인가요?","options":[{"t":"7일","correct":true},{"t":"5일","mis":"M2-2-u4-X15"},{"t":"30일","mis":"M2-2-u4-X14"}],"explanation":["달력의 한 줄에는 일요일부터 토요일까지 있어요.","7칸이라 7일 — 1주일이에요.","그래서 7일이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#2','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',1,'mc','auto','11월 14일은 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":2,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"11월 14일은 무슨 요일인가요?","explanation":["달력에서 14일을 찾아요.","14일이 있는 칸의 위를 따라 올라가면 토요일이에요.","같은 세로줄은 모두 같은 요일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"wday"}},"options":[{"t":"토요일","correct":true},{"t":"일요일","mis":"M2-2-u4-X17"},{"t":"금요일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#3','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',1,'mc','auto','4월은 며칠까지 있나요?',ARRAY['M2-2-u4-X18']::text[],true,'{"seq":3,"concept":"M2-2-u4-C9","difficulty":1,"kind":"mc","stem":"4월은 며칠까지 있나요?","explanation":["달마다 날수가 달라요.","4월은 30일까지 있어요.","주먹을 쥐고 손등의 튀어나온 곳을 31일, 들어간 곳을 30일로 세면 쉬워요(2월은 28일 또는 29일)."],"variant_rule":{"tm":{"ask":"units","form":"mdays"}},"options":[{"t":"30일","correct":true},{"t":"31일","mis":"M2-2-u4-X18"},{"t":"28일","mis":"M2-2-u4-X18"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#4','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',1,'mc','auto','1년은 몇 개월인가요?',ARRAY['M2-2-u4-X15']::text[],true,'{"seq":4,"concept":"M2-2-u4-C9","difficulty":1,"kind":"mc","stem":"1년은 몇 개월인가요?","options":[{"t":"12개월","correct":true},{"t":"10개월","mis":"M2-2-u4-X15"},{"t":"24개월","mis":"M2-2-u4-X15"}],"explanation":["1월부터 12월까지 달이 있어요.","모두 열두 달이에요.","그래서 1년은 12개월이에요."],"variant_rule":{"alt":[{"stem":"12개월은 몇 년인가요?","options":[{"t":"1년","correct":true},{"t":"12년","mis":"M2-2-u4-X14"},{"t":"2년","mis":"M2-2-u4-X15"}],"explanation":["1월부터 12월까지가 1년이에요.","열두 달 — 12개월이에요.","그래서 12개월은 1년이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#5','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',2,'sa','auto','11월의 둘째 토요일은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"11월의 둘째 토요일은 며칠인가요? 숫자로 쓰세요.","explanation":["11월의 첫째 토요일은 7일이에요.","한 주에 7일씩 — 7, 14예요.","그래서 둘째 토요일은 14일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"nth"}},"answer":["14"],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#6','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',2,'mc','auto','11월 7일에서 2주일 후는 며칠인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X17']::text[],true,'{"seq":6,"concept":"M2-2-u4-C8","difficulty":2,"kind":"mc","stem":"11월 7일에서 2주일 후는 며칠인가요?","explanation":["1주일은 7일 — 2주일은 14일이에요.","7 + 14 = 21이에요.","달력에서 아랫줄로 2칸 내려가면 같은 요일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"after","weeks":true}},"options":[{"t":"21일","correct":true},{"t":"9일","mis":"M2-2-u4-X15"},{"t":"22일","mis":"M2-2-u4-X17"},{"t":"20일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#7','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C8',2,'mc','auto','3주일은 며칠인가요?',ARRAY['M2-2-u4-X15']::text[],true,'{"seq":7,"concept":"M2-2-u4-C8","difficulty":2,"kind":"mc","stem":"3주일은 며칠인가요?","explanation":["1주일은 7일이에요.","3주일은 7일이 3번이에요.","7 + 7 + 7 = 21 — 21일이에요."],"variant_rule":{"tm":{"ask":"units","form":"wk2d"}},"options":[{"t":"21일","correct":true},{"t":"15일","mis":"M2-2-u4-X15"},{"t":"30일","mis":"M2-2-u4-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#8','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',2,'sa','auto','1년 6개월은 몇 개월인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M2-2-u4-C9","difficulty":2,"kind":"sa","stem":"1년 6개월은 몇 개월인가요? 숫자로 쓰세요.","explanation":["1년은 12개월이에요.","1년 6개월 = 12개월 + 6개월이에요.","그래서 18개월이에요."],"variant_rule":{"tm":{"ask":"units","form":"y2m"}},"answer":["18"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#9','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',2,'match','auto','같은 것끼리 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M2-2-u4-C9","difficulty":2,"kind":"match","stem":"같은 것끼리 이으세요.","pairs":[{"l":"1주일","r":"7일"},{"l":"1년","r":"12개월"},{"l":"1일","r":"24시간"}],"mis":"M2-2-u4-X15","explanation":["1주일은 7일이에요.","1년은 12개월이에요.","1일은 24시간이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 것끼리 이으세요.","pairs":[{"l":"2주일","r":"14일"},{"l":"2년","r":"24개월"},{"l":"1시간","r":"60분"}],"explanation":["2주일은 7일이 2번 — 14일이에요.","2년은 12개월이 2번 — 24개월이에요.","1시간은 60분이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_basic#10','math',2,2,'u4','L08','g2_2_math_u4_L08_basic','lesson_basic','M2-2-u4-C9',3,'error','auto','「12월」과 「12개월」에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u4-X14','M2-2-u4-X16']::text[],true,'{"seq":10,"concept":"M2-2-u4-C9","difficulty":3,"kind":"error","stem":"「12월」과 「12개월」에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「12월과 12개월은 같은 말이야.」","correct":true,"mis_target":"M2-2-u4-X14"},{"t":"아린 — 「12월은 달의 이름이야.」","mis":"M2-2-u4-X16"},{"t":"태민 — 「12개월은 열두 달 동안의 길이야.」","mis":"M2-2-u4-X16"}],"explanation":["12월은 1년 가운데 마지막 달의 이름이에요.","12개월은 열두 달 동안 — 1년의 길이예요.","지안이는 이름과 길이를 같게 보았어요."],"variant_rule":{"alt":[{"stem":"「3월」과 「3개월」에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「3월과 3개월은 같은 말이야.」","correct":true,"mis_target":"M2-2-u4-X14"},{"t":"아린 — 「3월은 달의 이름이야.」","mis":"M2-2-u4-X16"},{"t":"태민 — 「3개월은 세 달 동안의 길이야.」","mis":"M2-2-u4-X16"}],"explanation":["3월은 달의 이름이에요.","3개월은 세 달 동안의 길이예요.","지안이는 이름과 길이를 같게 보았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#1','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',2,'sa','auto','11월에 월요일은 모두 몇 번 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"11월에 월요일은 모두 몇 번 있나요? 숫자로 쓰세요.","explanation":["월요일 세로줄을 따라 날짜를 세어요.","2, 9, 16, 23, 30일 — 5번이에요.","빈칸은 세지 않아요."],"variant_rule":{"tm":{"ask":"cal","form":"count"}},"answer":["5"],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#2','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C9',2,'mc','auto','20개월은 몇 년 몇 개월인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X10']::text[],true,'{"seq":2,"concept":"M2-2-u4-C9","difficulty":2,"kind":"mc","stem":"20개월은 몇 년 몇 개월인가요?","explanation":["12개월은 1년이에요.","20개월 = 12개월 + 8개월이에요.","12개월은 1년이니 1년 8개월이에요."],"variant_rule":{"tm":{"ask":"units","form":"m2y"}},"options":[{"t":"1년 8개월","correct":true},{"t":"2년","mis":"M2-2-u4-X15"},{"t":"1년 9개월","mis":"M2-2-u4-X10"},{"t":"2년 8개월","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#3','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',3,'mc','auto','슬기는 매주 월요일과 수요일에 음악 줄넘기를 해요. 11월에 음악 줄넘기를 하는 날은 모두 며칠인가요?',ARRAY['M2-2-u4-X17','M2-2-u4-X14']::text[],false,'{"seq":3,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"슬기는 매주 월요일과 수요일에 음악 줄넘기를 해요. 11월에 음악 줄넘기를 하는 날은 모두 며칠인가요?","options":[{"t":"9일","correct":true},{"t":"8일","mis":"M2-2-u4-X17"},{"t":"10일","mis":"M2-2-u4-X17"},{"t":"2일","mis":"M2-2-u4-X14"}],"explanation":["월요일은 2, 9, 16, 23, 30일 — 5번이에요.","수요일은 4, 11, 18, 25일 — 4번이에요.","5 + 4 = 9 — 모두 9일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"2":"🎵","4":"🎵","9":"🎵","11":"🎵","16":"🎵","18":"🎵","23":"🎵","25":"🎵","30":"🎵"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#4','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',3,'mc','auto','11월 28일 토요일에서 2주일 뒤는 언제인가요?',ARRAY['M2-2-u4-X18','M2-2-u4-X17']::text[],false,'{"seq":4,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"11월 28일 토요일에서 2주일 뒤는 언제인가요?","options":[{"t":"12월 12일 토요일","correct":true},{"t":"11월 42일 토요일","mis":"M2-2-u4-X18"},{"t":"12월 14일 월요일","mis":"M2-2-u4-X17"},{"t":"12월 10일 목요일","mis":"M2-2-u4-X17"}],"explanation":["2주일은 14일이에요.","11월은 30일까지라 28일에서 2일 지나면 11월 30일, 12일 더 지나면 12월 12일이에요.","2주일 뒤는 같은 요일 — 토요일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#5','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C9',3,'mc','auto','날수가 31일인 달끼리 짝 지은 것은 어느 것인가요?',ARRAY['M2-2-u4-X18']::text[],false,'{"seq":5,"concept":"M2-2-u4-C9","difficulty":3,"kind":"mc","stem":"날수가 31일인 달끼리 짝 지은 것은 어느 것인가요?","options":[{"t":"7월, 8월","correct":true},{"t":"4월, 6월","mis":"M2-2-u4-X18"},{"t":"2월, 3월","mis":"M2-2-u4-X18"},{"t":"9월, 11월","mis":"M2-2-u4-X18"}],"explanation":["7월과 8월은 둘 다 31일까지 있어요.","4월·6월·9월·11월은 30일까지예요.","2월은 28일 또는 29일까지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#6','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',3,'mc','auto','연우 생일은 11월 14일이에요. 생일의 10일 후는 며칠인가요?',ARRAY['M2-2-u4-X17','M2-2-u4-X16']::text[],false,'{"seq":6,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"연우 생일은 11월 14일이에요. 생일의 10일 후는 며칠인가요?","options":[{"t":"11월 24일","correct":true},{"t":"11월 23일","mis":"M2-2-u4-X17"},{"t":"11월 25일","mis":"M2-2-u4-X17"},{"t":"11월 4일","mis":"M2-2-u4-X16"}],"explanation":["생일은 빼고 다음 날부터 세요 — 15일이 1일 후예요.","14 + 10 = 24예요.","그래서 11월 24일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30,"marks":{"14":"🎂"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#7','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',3,'ox','auto','2주일 3일은 17일이에요.',ARRAY['M2-2-u4-X15']::text[],false,'{"seq":7,"concept":"M2-2-u4-C8","difficulty":3,"kind":"ox","stem":"2주일 3일은 17일이에요.","answer":"O","reason_options":[{"t":"2주일은 14일이라 14 + 3 = 17일이니까","correct":true},{"t":"2주일 3일은 2 + 3 = 5일이니까","mis":"M2-2-u4-X15"}],"mis":"M2-2-u4-X15","explanation":["1주일은 7일 — 2주일은 14일이에요.","14일과 3일을 모으면 17일이에요.","그래서 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#8','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C8',4,'essay','teacher','11월 둘째 토요일부터 2주일마다 등산을 가요. 11월에 등산 가는 날을 모두 찾고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u4-C8","difficulty":4,"kind":"essay","stem":"11월 둘째 토요일부터 2주일마다 등산을 가요. 11월에 등산 가는 날을 모두 찾고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 11월 1일이 일요일이므로 첫째 토요일은 7일, 둘째 토요일은 14일이다. 2주일은 14일이므로 14일 다음은 28일이다. 등산 가는 날은 14일과 28일이다.","scoring_points":["둘째 토요일이 14일임을 찾았는가","2주일이 14일임을 썼는가","14일·28일을 찾았는가"]},"explanation":["첫째 토요일은 7일, 둘째 토요일은 14일이에요.","2주일 = 14일이라 14 + 14 = 28이에요.","등산 가는 날은 14일과 28일이에요."],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#9','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C9',4,'essay','teacher','「12월」과 「12개월」은 어떻게 다른지 예를 들어 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u4-C9","difficulty":4,"kind":"essay","stem":"「12월」과 「12개월」은 어떻게 다른지 예를 들어 설명해 보세요.","answer_guide":{"answer":"예: 12월은 1년 가운데 마지막 달의 이름이다. 12개월은 열두 달 동안의 길이로 1년과 같다. 「12월에 눈이 왔다」는 때를, 「12개월 동안 저금했다」는 길이를 나타낸다.","scoring_points":["12월이 달의 이름임을 썼는가","12개월이 기간(길이)임을 썼는가","알맞은 예를 들었는가"]},"explanation":["12월은 달의 이름이에요.","12개월은 열두 달 동안 — 1년이에요.","때를 말할 때와 길이를 말할 때가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_L08_challenge#10','math',2,2,'u4','L08','g2_2_math_u4_L08_challenge','lesson_challenge','M2-2-u4-C9',4,'mc','auto','지아는 15개월, 연우는 1년 2개월 동안 줄넘기를 했어요. 누가 몇 개월 더 오래 했나요?',ARRAY['M2-2-u4-X15','M2-2-u4-X10']::text[],false,'{"seq":10,"concept":"M2-2-u4-C9","difficulty":4,"kind":"mc","stem":"지아는 15개월, 연우는 1년 2개월 동안 줄넘기를 했어요. 누가 몇 개월 더 오래 했나요?","options":[{"t":"지아가 1개월 더","correct":true},{"t":"연우가 1개월 더","mis":"M2-2-u4-X15"},{"t":"지아가 13개월 더","mis":"M2-2-u4-X15"},{"t":"연우가 2개월 더","mis":"M2-2-u4-X10"}],"explanation":["1년 2개월은 12 + 2 = 14개월이에요.","15개월과 14개월을 견주면 15개월이 1개월 더 길어요.","그래서 지아가 1개월 더 오래 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#1','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 2시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 2시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 2와 3 사이에 있으니 2시예요.","긴바늘이 숫자 4를 가리키니 4 × 5 = 20분이에요.","그래서 2시 20분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"answer":["20"],"asset":{"type":"clock2","h":2,"m":20}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#2','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C1',1,'mc','auto','긴바늘이 숫자 4를 가리키면 몇 분인가요?',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":2,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"긴바늘이 숫자 4를 가리키면 몇 분인가요?","explanation":["숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","숫자 4까지 5분씩 4번이니 4 × 5 = 20이에요.","그래서 20분이에요 — 숫자 그대로 4분이 아니에요."],"variant_rule":{"tm":{"ask":"numm"}},"options":[{"t":"20분","correct":true},{"t":"4분","mis":"M2-2-u4-X02"},{"t":"40분","mis":"M2-2-u4-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#3','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C2',1,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],true,'{"seq":3,"concept":"M2-2-u4-C2","difficulty":1,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","10 : 35는 10시 35분이에요.","시는 「열 시」, 분은 「삼십오 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"열 시 삼십오 분","correct":true},{"t":"삼십오 시 열 분","mis":"M2-2-u4-X06"},{"t":"십 시 삼십오 분","mis":"M2-2-u4-X06"}],"asset":{"type":"digital","h":10,"m":35}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#4','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C3',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05']::text[],true,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 1과 2 사이에 있으니 1시예요.","긴바늘이 숫자 2(10분)에서 작은 눈금 3칸 더 간 곳이니 10 + 3 = 13분이에요.","그래서 1시 13분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"1시 13분","correct":true},{"t":"1시 14분","mis":"M2-2-u4-X04"},{"t":"1시 17분","mis":"M2-2-u4-X05"}],"asset":{"type":"clock2","h":1,"m":13}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#5','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C4',1,'sa','auto','8시 55분은 9시 몇 분 전인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":1,"kind":"sa","stem":"8시 55분은 9시 몇 분 전인가요? 숫자로 쓰세요.","explanation":["8시 55분에서 5분이 지나면 9시가 돼요.","그래서 8시 55분을 9시 5분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 9시예요 — 지금 시 8시가 아니에요."],"variant_rule":{"tm":{"ask":"before"}},"answer":["5"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#6','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C5',1,'sa','auto','수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 10시 30분, 끝난 시각은 11시 30분이에요.","칠한 칸이 6칸 — 한 칸이 10분이니 60분이에요.","1시간은 60분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["60"],"asset":{"type":"tbar","from":[10,30],"to":[11,30],"label":"수영을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#7','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C7',1,'mc','auto','하루는 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X09']::text[],false,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"하루는 몇 시간인가요?","options":[{"t":"24시간","correct":true},{"t":"12시간","mis":"M2-2-u4-X13"},{"t":"60시간","mis":"M2-2-u4-X09"}],"explanation":["짧은바늘이 하루에 두 바퀴 돌아요.","한 바퀴는 12시간이에요.","12 + 12 = 24 — 하루는 24시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#8','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C8',1,'mc','auto','11월 14일은 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":8,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"11월 14일은 무슨 요일인가요?","explanation":["달력에서 14일을 찾아요.","14일이 있는 칸의 위를 따라 올라가면 토요일이에요.","같은 세로줄은 모두 같은 요일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"wday"}},"options":[{"t":"토요일","correct":true},{"t":"일요일","mis":"M2-2-u4-X17"},{"t":"금요일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#9','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C4',2,'mc','auto','7시 5분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"7시 5분 전은 몇 시 몇 분인가요?","explanation":["7시 5분 전은 7시가 되기 5분 전이에요.","7시에서 긴바늘을 5분만큼 거꾸로 돌리면 6시 55분이에요.","짧은바늘은 아직 6과 7 사이에 있어서 6시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"6시 55분","correct":true},{"t":"7시 55분","mis":"M2-2-u4-X07"},{"t":"7시 5분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#10','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C6',2,'mc','auto','1시간 10분은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"1시간 10분은 몇 분인가요?","explanation":["1시간은 60분이에요.","1시간 10분 = 60분 + 10분이에요.","그래서 70분이에요 — 1시간을 100분으로 보면 안 돼요."],"variant_rule":{"tm":{"ask":"h60","form":"tomin"}},"options":[{"t":"70분","correct":true},{"t":"110분","mis":"M2-2-u4-X09"},{"t":"80분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#11','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C6',2,'mc','auto','80분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":11,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"80분은 몇 시간 몇 분인가요?","explanation":["60분은 1시간이에요.","80분 = 60분 + 20분이에요.","60분은 1시간이니 1시간 20분이에요."],"variant_rule":{"tm":{"ask":"h60","form":"tohm"}},"options":[{"t":"1시간 20분","correct":true},{"t":"8시간","mis":"M2-2-u4-X09"},{"t":"1시간 30분","mis":"M2-2-u4-X10"},{"t":"1시간 10분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#12','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C6',2,'mc','auto','피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":12,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?","explanation":["시작한 시각은 9시, 끝난 시각은 10시 10분이에요.","9시에서 1시간 뒤인 10시를 먼저 찾고 남은 만큼 더 세면 1시간 10분이에요.","70분 = 1시간 10분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"pair","unit":"hm"}},"options":[{"t":"1시간 10분","correct":true},{"t":"10시간 10분","mis":"M2-2-u4-X11"},{"t":"1시간 20분","mis":"M2-2-u4-X10"}],"asset":{"type":"dpair","a":[9,0],"b":[10,10]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#13','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C7',2,'sa','auto','1일 5시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"1일 5시간은 몇 시간인가요? 숫자로 쓰세요.","explanation":["하루는 24시간이에요 — 짧은바늘이 두 바퀴 돌아요.","1일 5시간 = 24시간 + 5시간이에요.","그래서 29시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"toh"}},"answer":["29"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#14','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C7',2,'mc','auto','오전 11시에 피아노 연습을 시작해서 2시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":14,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 11시에 피아노 연습을 시작해서 2시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 11시에서 1시간 뒤가 낮 12시, 거기서 1시간 더 가면 오후 1시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 1시","correct":true},{"t":"오전 1시","mis":"M2-2-u4-X12"},{"t":"오후 13시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#15','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C9',2,'sa','auto','1년 6개월은 몇 개월인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M2-2-u4-C9","difficulty":2,"kind":"sa","stem":"1년 6개월은 몇 개월인가요? 숫자로 쓰세요.","explanation":["1년은 12개월이에요.","1년 6개월 = 12개월 + 6개월이에요.","그래서 18개월이에요."],"variant_rule":{"tm":{"ask":"units","form":"y2m"}},"answer":["18"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#16','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C8',2,'sa','auto','11월의 둘째 토요일은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"11월의 둘째 토요일은 며칠인가요? 숫자로 쓰세요.","explanation":["11월의 첫째 토요일은 7일이에요.","한 주에 7일씩 — 7, 14예요.","그래서 둘째 토요일은 14일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"nth"}},"answer":["14"],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#17','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C3',3,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X03']::text[],true,'{"seq":17,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 11과 12 사이에 있으니 11시예요.","긴바늘이 숫자 11(55분)에서 작은 눈금 1칸 더 간 곳이니 55 + 1 = 56분이에요.","그래서 11시 56분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"11시 56분","correct":true},{"t":"11시 57분","mis":"M2-2-u4-X04"},{"t":"12시 56분","mis":"M2-2-u4-X03"},{"t":"11시 50분","mis":"M2-2-u4-X04"}],"asset":{"type":"clock2","h":11,"m":56}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#18','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C6',3,'mc','auto','2시 40분에 피아노 연습을 시작해서 1시간 30분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":18,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"2시 40분에 피아노 연습을 시작해서 1시간 30분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","explanation":["시작한 시각 2시 40분에서 1시간 30분이 지난 시각을 찾아요.","1시간 뒤는 3시 40분, 거기서 30분 더 지나면 4시 10분이에요.","분이 60분이 되면 시가 하나 커져요."],"variant_rule":{"tm":{"ask":"after"}},"options":[{"t":"4시 10분","correct":true},{"t":"3시 70분","mis":"M2-2-u4-X09"},{"t":"4시 20분","mis":"M2-2-u4-X10"},{"t":"4시","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#19','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C8',3,'mc','auto','11월 14일에서 10일 후는 며칠인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":19,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"11월 14일에서 10일 후는 며칠인가요?","explanation":["14일은 빼고 다음 날부터 하루씩 세어요.","14 + 10 = 24예요.","그래서 11월 24일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"after"}},"options":[{"t":"24일","correct":true},{"t":"23일","mis":"M2-2-u4-X17"},{"t":"25일","mis":"M2-2-u4-X17"},{"t":"22일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":11,"start":0,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#20','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C10',3,'mc','auto','슬기가 처음 세발자전거를 탄 날은 2022년 5월 12일, 처음 줄넘기를 성공한 날은 2024년 5월 12일이에요. 몇 년 후인가요?',ARRAY['M2-2-u4-X14','M2-2-u4-X15']::text[],false,'{"seq":20,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"슬기가 처음 세발자전거를 탄 날은 2022년 5월 12일, 처음 줄넘기를 성공한 날은 2024년 5월 12일이에요. 몇 년 후인가요?","options":[{"t":"2년 후","correct":true},{"t":"12년 후","mis":"M2-2-u4-X14"},{"t":"2개월 후","mis":"M2-2-u4-X15"}],"explanation":["월과 일은 5월 12일로 같아요.","2022년에서 2024년으로 년만 2 커졌어요.","그래서 2년 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#21','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C10',3,'mc','auto','2025년 4월 22일에서 1년 후는 언제인가요?',ARRAY['M2-2-u4-X15']::text[],false,'{"seq":21,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"2025년 4월 22일에서 1년 후는 언제인가요?","options":[{"t":"2026년 4월 22일","correct":true},{"t":"2025년 5월 22일","mis":"M2-2-u4-X15"},{"t":"2025년 4월 23일","mis":"M2-2-u4-X15"}],"explanation":["1년 후는 년만 1 커져요.","월과 일은 그대로예요.","그래서 2026년 4월 22일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#22','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C5',3,'mc','auto','2시에서 5시가 될 때까지 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":22,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"2시에서 5시가 될 때까지 긴바늘은 몇 바퀴 돌았나요?","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","2시부터 5시까지 3시간이 지났어요.","그래서 긴바늘은 3바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"options":[{"t":"3바퀴","correct":true},{"t":"5바퀴","mis":"M2-2-u4-X11"},{"t":"4바퀴","mis":"M2-2-u4-X10"},{"t":"2바퀴","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#23','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C4',4,'essay','teacher','10시 50분을 「몇 시 몇 분 전」으로 나타내고, 그렇게 나타낸 방법을 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u4-C4","difficulty":4,"kind":"essay","stem":"10시 50분을 「몇 시 몇 분 전」으로 나타내고, 그렇게 나타낸 방법을 설명해 보세요.","answer_guide":{"answer":"예: 10시 50분에서 10분이 지나면 11시가 된다. 「몇 시 전」의 시는 곧 될 정각이므로 10시 50분은 11시 10분 전이다.","scoring_points":["정각까지 10분 남았음을 썼는가","곧 될 정각 11시를 썼는가","11시 10분 전이라고 나타냈는가"]},"explanation":["10시 50분에서 10분이 지나면 11시예요.","「전」의 시는 곧 될 정각이에요.","그래서 11시 10분 전이에요."],"asset":{"type":"clock2","h":10,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#24','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C10',4,'essay','teacher','슬기가 처음 세발자전거를 탄 날은 2022년 5월 12일, 처음 두발자전거를 탄 날은 2024년 7월 12일이에요. 몇 년 몇 개월 후인지 구하고, 몇 개월인지도 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u4-C10","difficulty":4,"kind":"essay","stem":"슬기가 처음 세발자전거를 탄 날은 2022년 5월 12일, 처음 두발자전거를 탄 날은 2024년 7월 12일이에요. 몇 년 몇 개월 후인지 구하고, 몇 개월인지도 설명해 보세요.","answer_guide":{"answer":"예: 2022년에서 2024년은 2년 후, 5월에서 7월은 2개월 후이므로 2년 2개월 후이다. 1년은 12개월이라 2년은 24개월, 24 + 2 = 26개월이다.","scoring_points":["두 날짜 사이의 년·개월·주를 바르게 찾았는가","1년 = 12개월, 1주일 = 7일을 바르게 썼는가","날짜나 기간을 단위와 함께 바르게 썼는가"]},"explanation":["년이 바뀌면 년을, 월이 바뀌면 개월을 세요.","주는 7일씩 — 달의 날수도 따져요.","날짜와 기간을 단위와 함께 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_a#25','math',2,2,'u4','','g2_2_math_u4_review_a','unit_review','M2-2-u4-C10',4,'mc','auto','2022년 5월 12일부터 2024년 7월 12일까지는 몇 개월인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X14']::text[],false,'{"seq":25,"concept":"M2-2-u4-C10","difficulty":4,"kind":"mc","stem":"2022년 5월 12일부터 2024년 7월 12일까지는 몇 개월인가요?","options":[{"t":"26개월","correct":true},{"t":"22개월","mis":"M2-2-u4-X15"},{"t":"4개월","mis":"M2-2-u4-X15"},{"t":"2개월","mis":"M2-2-u4-X14"}],"explanation":["2022년 5월에서 2024년 5월까지 2년 — 24개월이에요.","5월에서 7월까지 2개월이에요.","24 + 2 = 26개월이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#1','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 7시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 7시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 7과 8 사이에 있으니 7시예요.","긴바늘이 숫자 2를 가리키니 2 × 5 = 10분이에요.","그래서 7시 10분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"answer":["10"],"asset":{"type":"clock2","h":7,"m":10}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#2','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C1',1,'mc','auto','긴바늘이 숫자 7을 가리키면 몇 분인가요?',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":2,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"긴바늘이 숫자 7을 가리키면 몇 분인가요?","explanation":["숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","숫자 7까지 5분씩 7번이니 7 × 5 = 35예요.","그래서 35분이에요 — 숫자 그대로 7분이 아니에요."],"variant_rule":{"tm":{"ask":"numm"}},"options":[{"t":"35분","correct":true},{"t":"7분","mis":"M2-2-u4-X02"},{"t":"70분","mis":"M2-2-u4-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#3','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C2',1,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],true,'{"seq":3,"concept":"M2-2-u4-C2","difficulty":1,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","11 : 43은 11시 43분이에요.","시는 「열한 시」, 분은 「사십삼 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"열한 시 사십삼 분","correct":true},{"t":"사십삼 시 열한 분","mis":"M2-2-u4-X06"},{"t":"십일 시 사십삼 분","mis":"M2-2-u4-X06"}],"asset":{"type":"digital","h":11,"m":43}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#4','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C3',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05']::text[],true,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 4와 5 사이에 있으니 4시예요.","긴바늘이 숫자 5(25분)에서 작은 눈금 3칸 더 간 곳이니 25 + 3 = 28분이에요.","그래서 4시 28분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"4시 28분","correct":true},{"t":"4시 29분","mis":"M2-2-u4-X04"},{"t":"4시 32분","mis":"M2-2-u4-X05"}],"asset":{"type":"clock2","h":4,"m":28}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#5','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C4',1,'sa','auto','3시 50분은 4시 몇 분 전인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":1,"kind":"sa","stem":"3시 50분은 4시 몇 분 전인가요? 숫자로 쓰세요.","explanation":["3시 50분에서 10분이 지나면 4시가 돼요.","그래서 3시 50분을 4시 10분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 4시예요 — 지금 시 3시가 아니에요."],"variant_rule":{"tm":{"ask":"before"}},"answer":["10"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#6','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C5',1,'sa','auto','수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 9시, 끝난 시각은 11시예요.","칠한 칸이 12칸 — 한 칸이 10분이니 120분이에요.","2시간은 60분씩 2번 — 120분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["120"],"asset":{"type":"tbar","from":[9,0],"to":[11,0],"label":"수영을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#7','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C7',1,'mc','auto','밤 12시부터 낮 12시까지를 무엇이라고 하나요?',ARRAY['M2-2-u4-X12','M2-2-u4-X13']::text[],false,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"밤 12시부터 낮 12시까지를 무엇이라고 하나요?","options":[{"t":"오전","correct":true},{"t":"오후","mis":"M2-2-u4-X12"},{"t":"하루","mis":"M2-2-u4-X13"}],"explanation":["하루는 낮 12시에서 오전과 오후로 나뉘어요.","밤 12시부터 낮 12시까지가 오전이에요.","그래서 오전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#8','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C8',1,'mc','auto','10월 20일은 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":8,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"10월 20일은 무슨 요일인가요?","explanation":["달력에서 20일을 찾아요.","20일이 있는 칸의 위를 따라 올라가면 화요일이에요.","같은 세로줄은 모두 같은 요일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"wday"}},"options":[{"t":"화요일","correct":true},{"t":"수요일","mis":"M2-2-u4-X17"},{"t":"월요일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":10,"start":4,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#9','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C4',2,'mc','auto','10시 10분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"10시 10분 전은 몇 시 몇 분인가요?","explanation":["10시 10분 전은 10시가 되기 10분 전이에요.","10시에서 긴바늘을 10분만큼 거꾸로 돌리면 9시 50분이에요.","짧은바늘은 아직 9와 10 사이에 있어서 9시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"9시 50분","correct":true},{"t":"10시 50분","mis":"M2-2-u4-X07"},{"t":"10시 10분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#10','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',2,'mc','auto','1시간 40분은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"1시간 40분은 몇 분인가요?","explanation":["1시간은 60분이에요.","1시간 40분 = 60분 + 40분이에요.","그래서 100분이에요 — 1시간을 100분으로 보면 안 돼요."],"variant_rule":{"tm":{"ask":"h60","form":"tomin"}},"options":[{"t":"100분","correct":true},{"t":"140분","mis":"M2-2-u4-X09"},{"t":"110분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#11','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',2,'mc','auto','100분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":11,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"100분은 몇 시간 몇 분인가요?","explanation":["60분은 1시간이에요.","100분 = 60분 + 40분이에요.","60분은 1시간이니 1시간 40분이에요."],"variant_rule":{"tm":{"ask":"h60","form":"tohm"}},"options":[{"t":"1시간 40분","correct":true},{"t":"1시간","mis":"M2-2-u4-X09"},{"t":"10시간","mis":"M2-2-u4-X09"},{"t":"1시간 50분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#12','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',2,'mc','auto','피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":12,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?","explanation":["시작한 시각은 10시 40분, 끝난 시각은 12시예요.","10시 40분에서 1시간 뒤인 11시 40분을 먼저 찾고 남은 만큼 더 세면 1시간 20분이에요.","80분 = 1시간 20분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"pair","unit":"hm"}},"options":[{"t":"1시간 20분","correct":true},{"t":"12시간","mis":"M2-2-u4-X11"},{"t":"1시간 30분","mis":"M2-2-u4-X10"}],"asset":{"type":"dpair","a":[10,40],"b":[12,0]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#13','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C7',2,'sa','auto','1일 10시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"1일 10시간은 몇 시간인가요? 숫자로 쓰세요.","explanation":["하루는 24시간이에요 — 짧은바늘이 두 바퀴 돌아요.","1일 10시간 = 24시간 + 10시간이에요.","그래서 34시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"toh"}},"answer":["34"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#14','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C7',2,'mc','auto','오전 10시에 피아노 연습을 시작해서 4시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":14,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 10시에 피아노 연습을 시작해서 4시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 10시에서 2시간 뒤가 낮 12시, 거기서 2시간 더 가면 오후 2시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 2시","correct":true},{"t":"오전 2시","mis":"M2-2-u4-X12"},{"t":"오후 14시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#15','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C9',2,'sa','auto','2년 3개월은 몇 개월인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M2-2-u4-C9","difficulty":2,"kind":"sa","stem":"2년 3개월은 몇 개월인가요? 숫자로 쓰세요.","explanation":["1년은 12개월이에요.","2년은 12개월이 2번 — 24개월이에요.","그래서 27개월이에요."],"variant_rule":{"tm":{"ask":"units","form":"y2m"}},"answer":["27"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#16','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C8',2,'sa','auto','10월의 셋째 일요일은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"10월의 셋째 일요일은 며칠인가요? 숫자로 쓰세요.","explanation":["10월의 첫째 일요일은 4일이에요.","한 주에 7일씩 — 4, 11, 18이에요.","그래서 셋째 일요일은 18일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"nth"}},"answer":["18"],"asset":{"type":"cal","mon":10,"start":4,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#17','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C3',3,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X03']::text[],true,'{"seq":17,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 2와 3 사이에 있으니 2시예요.","긴바늘이 숫자 11(55분)에서 작은 눈금 4칸 더 간 곳이니 55 + 4 = 59분이에요.","그래서 2시 59분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"2시 59분","correct":true},{"t":"2시 57분","mis":"M2-2-u4-X04"},{"t":"3시 59분","mis":"M2-2-u4-X03"},{"t":"2시 50분","mis":"M2-2-u4-X04"}],"asset":{"type":"clock2","h":2,"m":59}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#18','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',3,'mc','auto','9시 30분에 피아노 연습을 시작해서 50분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":18,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"9시 30분에 피아노 연습을 시작해서 50분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","explanation":["시작한 시각 9시 30분에서 50분이 지난 시각을 찾아요.","50분 뒤는 10시 20분이에요.","분이 60분이 되면 시가 하나 커져요."],"variant_rule":{"tm":{"ask":"after"}},"options":[{"t":"10시 20분","correct":true},{"t":"9시 80분","mis":"M2-2-u4-X09"},{"t":"10시 30분","mis":"M2-2-u4-X10"},{"t":"10시 10분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#19','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C8',3,'mc','auto','10월 25일에서 6일 전은 며칠인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":19,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"10월 25일에서 6일 전은 며칠인가요?","explanation":["25일은 빼고 전날부터 하루씩 세어요.","25 − 6 = 19예요.","그래서 10월 19일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"before"}},"options":[{"t":"19일","correct":true},{"t":"20일","mis":"M2-2-u4-X17"},{"t":"18일","mis":"M2-2-u4-X17"},{"t":"12일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":10,"start":4,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#20','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C10',3,'mc','auto','처음 줄넘기를 성공한 날 2024년 5월 12일에서 처음 두발자전거를 탄 날 2024년 7월 12일은 몇 개월 후인가요?',ARRAY['M2-2-u4-X14','M2-2-u4-X15']::text[],false,'{"seq":20,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"처음 줄넘기를 성공한 날 2024년 5월 12일에서 처음 두발자전거를 탄 날 2024년 7월 12일은 몇 개월 후인가요?","options":[{"t":"2개월 후","correct":true},{"t":"7개월 후","mis":"M2-2-u4-X14"},{"t":"2년 후","mis":"M2-2-u4-X15"}],"explanation":["년과 일은 같아요.","5월에서 7월로 월만 2 커졌어요.","그래서 2개월 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#21','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C10',3,'mc','auto','2024년 12월 22일에서 4개월 후는 언제인가요?',ARRAY['M2-2-u4-X10','M2-2-u4-X15']::text[],false,'{"seq":21,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"2024년 12월 22일에서 4개월 후는 언제인가요?","options":[{"t":"2025년 4월 22일","correct":true},{"t":"2024년 4월 22일","mis":"M2-2-u4-X10"},{"t":"2024년 12월 26일","mis":"M2-2-u4-X15"}],"explanation":["12월에서 1개월 후는 다음 해 1월이에요.","1월, 2월, 3월, 4월 — 4개월 후는 2025년 4월이에요.","일은 그대로 22일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#22','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C5',3,'mc','auto','5시 30분에서 9시 30분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":22,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"5시 30분에서 9시 30분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","5시 30분부터 9시 30분까지 4시간이 지났어요.","그래서 긴바늘은 4바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"options":[{"t":"4바퀴","correct":true},{"t":"9바퀴","mis":"M2-2-u4-X11"},{"t":"5바퀴","mis":"M2-2-u4-X10"},{"t":"3바퀴","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#23','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C6',4,'essay','teacher','오후 2시 20분에 영화가 시작해서 오후 3시 30분에 끝났어요. 영화를 본 시간을 몇 분으로 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u4-C6","difficulty":4,"kind":"essay","stem":"오후 2시 20분에 영화가 시작해서 오후 3시 30분에 끝났어요. 영화를 본 시간을 몇 분으로 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 2시 20분에서 1시간 뒤는 3시 20분이고 10분 더 가서 1시간 10분이다. 1시간은 60분이므로 60 + 10 = 70분이다.","scoring_points":["1시간을 먼저 찾고 남은 만큼 셈했는가","1시간 10분을 구했는가","70분으로 바꾸었는가"]},"explanation":["2시 20분에서 1시간 뒤는 3시 20분이에요.","10분 더 가서 1시간 10분이에요.","60 + 10 = 70분이에요."],"asset":{"type":"dpair","a":[2,20],"b":[3,30]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#24','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C10',4,'essay','teacher','2024년 7월 12일에서 2024년 7월 26일은 몇 주 후인지 구하고, 년·개월과 달리 주를 셀 때 조심할 점을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u4-C10","difficulty":4,"kind":"essay","stem":"2024년 7월 12일에서 2024년 7월 26일은 몇 주 후인지 구하고, 년·개월과 달리 주를 셀 때 조심할 점을 설명해 보세요.","answer_guide":{"answer":"예: 12일에서 26일까지는 14일이고 1주일은 7일이므로 2주 후이다. 주는 7일씩 더해야 해서 달을 넘어가면 그 달의 날수를 따져야 한다.","scoring_points":["두 날짜 사이의 년·개월·주를 바르게 찾았는가","1년 = 12개월, 1주일 = 7일을 바르게 썼는가","날짜나 기간을 단위와 함께 바르게 썼는가"]},"explanation":["년이 바뀌면 년을, 월이 바뀌면 개월을 세요.","주는 7일씩 — 달의 날수도 따져요.","날짜와 기간을 단위와 함께 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_b#25','math',2,2,'u4','','g2_2_math_u4_review_b','unit_review','M2-2-u4-C10',4,'mc','auto','2022년 5월 12일에서 2년 2개월 2주 후는 언제인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X10','M2-2-u4-X14']::text[],false,'{"seq":25,"concept":"M2-2-u4-C10","difficulty":4,"kind":"mc","stem":"2022년 5월 12일에서 2년 2개월 2주 후는 언제인가요?","options":[{"t":"2024년 7월 26일","correct":true},{"t":"2024년 7월 14일","mis":"M2-2-u4-X15"},{"t":"2024년 5월 26일","mis":"M2-2-u4-X10"},{"t":"2024년 9월 12일","mis":"M2-2-u4-X14"}],"explanation":["2년 후는 2024년 5월 12일, 2개월 더 가면 2024년 7월 12일이에요.","2주는 14일 — 12 + 14 = 26이에요.","그래서 2024년 7월 26일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#1','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 4시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 4시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 4와 5 사이에 있으니 4시예요.","긴바늘이 숫자 9를 가리키니 9 × 5 = 45분이에요.","그래서 4시 45분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"answer":["45"],"asset":{"type":"clock2","h":4,"m":45}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#2','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C1',1,'mc','auto','긴바늘이 숫자 9를 가리키면 몇 분인가요?',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":2,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"긴바늘이 숫자 9를 가리키면 몇 분인가요?","explanation":["숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","숫자 9까지 5분씩 9번이니 9 × 5 = 45예요.","그래서 45분이에요 — 숫자 그대로 9분이 아니에요."],"variant_rule":{"tm":{"ask":"numm"}},"options":[{"t":"45분","correct":true},{"t":"9분","mis":"M2-2-u4-X02"},{"t":"90분","mis":"M2-2-u4-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#3','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C2',1,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],true,'{"seq":3,"concept":"M2-2-u4-C2","difficulty":1,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","6 : 50은 6시 50분이에요.","시는 「여섯 시」, 분은 「오십 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"여섯 시 오십 분","correct":true},{"t":"오십 시 여섯 분","mis":"M2-2-u4-X06"},{"t":"육 시 오십 분","mis":"M2-2-u4-X06"}],"asset":{"type":"digital","h":6,"m":50}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#4','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C3',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05']::text[],true,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 9와 10 사이에 있으니 9시예요.","긴바늘이 숫자 8(40분)에서 작은 눈금 1칸 더 간 곳이니 40 + 1 = 41분이에요.","그래서 9시 41분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"9시 41분","correct":true},{"t":"9시 42분","mis":"M2-2-u4-X04"},{"t":"9시 49분","mis":"M2-2-u4-X05"}],"asset":{"type":"clock2","h":9,"m":41}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#5','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C4',1,'sa','auto','6시 45분은 7시 몇 분 전인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":1,"kind":"sa","stem":"6시 45분은 7시 몇 분 전인가요? 숫자로 쓰세요.","explanation":["6시 45분에서 15분이 지나면 7시가 돼요.","그래서 6시 45분을 7시 15분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 7시예요 — 지금 시 6시가 아니에요."],"variant_rule":{"tm":{"ask":"before"}},"answer":["15"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#6','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C5',1,'sa','auto','수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 2시 20분, 끝난 시각은 3시 20분이에요.","칠한 칸이 6칸 — 한 칸이 10분이니 60분이에요.","1시간은 60분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["60"],"asset":{"type":"tbar","from":[2,20],"to":[3,20],"label":"수영을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#7','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C7',1,'mc','auto','낮 12시부터 밤 12시까지를 무엇이라고 하나요?',ARRAY['M2-2-u4-X12','M2-2-u4-X13']::text[],false,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"낮 12시부터 밤 12시까지를 무엇이라고 하나요?","options":[{"t":"오후","correct":true},{"t":"오전","mis":"M2-2-u4-X12"},{"t":"하루","mis":"M2-2-u4-X13"}],"explanation":["하루는 낮 12시에서 오전과 오후로 나뉘어요.","낮 12시부터 밤 12시까지가 오후예요.","그래서 오후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#8','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C8',1,'mc','auto','3월 17일은 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":8,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"3월 17일은 무슨 요일인가요?","explanation":["달력에서 17일을 찾아요.","17일이 있는 칸의 위를 따라 올라가면 화요일이에요.","같은 세로줄은 모두 같은 요일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"wday"}},"options":[{"t":"화요일","correct":true},{"t":"수요일","mis":"M2-2-u4-X17"},{"t":"월요일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":3,"start":0,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#9','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C4',2,'mc','auto','4시 15분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"4시 15분 전은 몇 시 몇 분인가요?","explanation":["4시 15분 전은 4시가 되기 15분 전이에요.","4시에서 긴바늘을 15분만큼 거꾸로 돌리면 3시 45분이에요.","짧은바늘은 아직 3과 4 사이에 있어서 3시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"3시 45분","correct":true},{"t":"4시 45분","mis":"M2-2-u4-X07"},{"t":"4시 15분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#10','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C6',2,'mc','auto','2시간 15분은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"2시간 15분은 몇 분인가요?","explanation":["1시간은 60분이에요.","2시간은 60분이 2번 — 120분이에요.","그래서 135분이에요 — 1시간을 100분으로 보면 안 돼요."],"variant_rule":{"tm":{"ask":"h60","form":"tomin"}},"options":[{"t":"135분","correct":true},{"t":"215분","mis":"M2-2-u4-X09"},{"t":"145분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#11','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C6',2,'mc','auto','135분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":11,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"135분은 몇 시간 몇 분인가요?","explanation":["60분은 1시간이에요.","135분 = 120분 + 15분이에요.","120분은 2시간이니 2시간 15분이에요."],"variant_rule":{"tm":{"ask":"h60","form":"tohm"}},"options":[{"t":"2시간 15분","correct":true},{"t":"1시간 35분","mis":"M2-2-u4-X09"},{"t":"13시간 5분","mis":"M2-2-u4-X09"},{"t":"2시간 25분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#12','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C6',2,'mc','auto','피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":12,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?","explanation":["시작한 시각은 1시 20분, 끝난 시각은 3시예요.","1시 20분에서 1시간 뒤인 2시 20분을 먼저 찾고 남은 만큼 더 세면 1시간 40분이에요.","100분 = 1시간 40분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"pair","unit":"hm"}},"options":[{"t":"1시간 40분","correct":true},{"t":"3시간","mis":"M2-2-u4-X11"},{"t":"1시간 50분","mis":"M2-2-u4-X10"}],"asset":{"type":"dpair","a":[1,20],"b":[3,0]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#13','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C7',2,'sa','auto','2일은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"2일은 몇 시간인가요? 숫자로 쓰세요.","explanation":["하루는 24시간이에요 — 짧은바늘이 두 바퀴 돌아요.","2일은 24시간이 2번 — 48시간이에요.","그래서 48시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"toh"}},"answer":["48"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#14','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C7',2,'mc','auto','오전 9시에 피아노 연습을 시작해서 5시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":14,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 9시에 피아노 연습을 시작해서 5시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 9시에서 3시간 뒤가 낮 12시, 거기서 2시간 더 가면 오후 2시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 2시","correct":true},{"t":"오전 2시","mis":"M2-2-u4-X12"},{"t":"오후 14시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#15','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C9',2,'sa','auto','1년 9개월은 몇 개월인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M2-2-u4-C9","difficulty":2,"kind":"sa","stem":"1년 9개월은 몇 개월인가요? 숫자로 쓰세요.","explanation":["1년은 12개월이에요.","1년 9개월 = 12개월 + 9개월이에요.","그래서 21개월이에요."],"variant_rule":{"tm":{"ask":"units","form":"y2m"}},"answer":["21"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#16','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C8',2,'sa','auto','5월의 둘째 수요일은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"5월의 둘째 수요일은 며칠인가요? 숫자로 쓰세요.","explanation":["5월의 첫째 수요일은 6일이에요.","한 주에 7일씩 — 6, 13이에요.","그래서 둘째 수요일은 13일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"nth"}},"answer":["13"],"asset":{"type":"cal","mon":5,"start":5,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#17','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C3',3,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05','M2-2-u4-X03']::text[],true,'{"seq":17,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 7과 8 사이에 있으니 7시예요.","긴바늘이 숫자 10(50분)에서 작은 눈금 3칸 더 간 곳이니 50 + 3 = 53분이에요.","그래서 7시 53분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"7시 53분","correct":true},{"t":"7시 54분","mis":"M2-2-u4-X04"},{"t":"7시 57분","mis":"M2-2-u4-X05"},{"t":"8시 53분","mis":"M2-2-u4-X03"}],"asset":{"type":"clock2","h":7,"m":53}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#18','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C6',3,'mc','auto','10시 45분에 피아노 연습을 시작해서 1시간 20분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":18,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"10시 45분에 피아노 연습을 시작해서 1시간 20분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","explanation":["시작한 시각 10시 45분에서 1시간 20분이 지난 시각을 찾아요.","1시간 뒤는 11시 45분, 거기서 20분 더 지나면 12시 5분이에요.","분이 60분이 되면 시가 하나 커져요."],"variant_rule":{"tm":{"ask":"after"}},"options":[{"t":"12시 5분","correct":true},{"t":"11시 65분","mis":"M2-2-u4-X09"},{"t":"12시 15분","mis":"M2-2-u4-X10"},{"t":"11시 55분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#19','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C8',3,'mc','auto','7월 12일에서 9일 후는 며칠인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":19,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"7월 12일에서 9일 후는 며칠인가요?","explanation":["12일은 빼고 다음 날부터 하루씩 세어요.","12 + 9 = 21이에요.","그래서 7월 21일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"after"}},"options":[{"t":"21일","correct":true},{"t":"20일","mis":"M2-2-u4-X17"},{"t":"22일","mis":"M2-2-u4-X17"},{"t":"28일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":7,"start":3,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#20','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C10',3,'mc','auto','2024년 7월 12일에서 처음 혼자서 수영한 날 2024년 7월 26일은 몇 주 후인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X14']::text[],false,'{"seq":20,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"2024년 7월 12일에서 처음 혼자서 수영한 날 2024년 7월 26일은 몇 주 후인가요?","options":[{"t":"2주 후","correct":true},{"t":"14주 후","mis":"M2-2-u4-X15"},{"t":"26주 후","mis":"M2-2-u4-X14"}],"explanation":["12일에서 26일까지는 14일이에요.","1주일은 7일이라 14일은 2주일이에요.","그래서 2주 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#21','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C10',3,'mc','auto','7월 12일에서 2주 후는 7월 며칠인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X14']::text[],false,'{"seq":21,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"7월 12일에서 2주 후는 7월 며칠인가요?","options":[{"t":"7월 26일","correct":true},{"t":"7월 14일","mis":"M2-2-u4-X15"},{"t":"9월 12일","mis":"M2-2-u4-X14"}],"explanation":["2주는 14일이에요.","12 + 14 = 26이에요.","그래서 7월 26일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#22','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C5',3,'mc','auto','1시 20분에서 7시 20분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10','M2-2-u4-X09']::text[],true,'{"seq":22,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"1시 20분에서 7시 20분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","1시 20분부터 7시 20분까지 6시간이 지났어요.","그래서 긴바늘은 6바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"options":[{"t":"6바퀴","correct":true},{"t":"7바퀴","mis":"M2-2-u4-X11"},{"t":"5바퀴","mis":"M2-2-u4-X10"},{"t":"360바퀴","mis":"M2-2-u4-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#23','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C3',4,'essay','teacher','11시 55분을 보고 「12시 55분」이라고 읽은 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 읽어 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u4-C3","difficulty":4,"kind":"essay","stem":"11시 55분을 보고 「12시 55분」이라고 읽은 친구가 있어요. 무엇이 잘못되었는지 설명하고 바르게 읽어 보세요.","answer_guide":{"answer":"예: 짧은바늘이 12에 아주 가까이 있지만 아직 11과 12 사이에 있다. 그래서 시는 11시이고, 긴바늘이 11을 가리키니 55분이다. 바른 시각은 11시 55분이다.","scoring_points":["짧은바늘이 아직 11과 12 사이임을 썼는가","시가 11시임을 썼는가","11시 55분이라고 바르게 읽었는가"]},"explanation":["짧은바늘은 12에 닿지 않았어요 — 11과 12 사이예요.","그래서 시는 11시예요.","긴바늘이 11 — 55분, 11시 55분이에요."],"asset":{"type":"clock2","h":11,"m":55}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#24','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C10',4,'essay','teacher','2024년 12월 1일에 수영을 배우고 3주 후에 스케이트를 탔어요. 스케이트를 탄 날에서 4개월 후에 배드민턴을 했어요. 배드민턴을 한 날은 언제인지 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u4-C10","difficulty":4,"kind":"essay","stem":"2024년 12월 1일에 수영을 배우고 3주 후에 스케이트를 탔어요. 스케이트를 탄 날에서 4개월 후에 배드민턴을 했어요. 배드민턴을 한 날은 언제인지 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 3주는 21일이므로 스케이트를 탄 날은 2024년 12월 22일이다. 12월에서 4개월 후는 다음 해 4월이므로 배드민턴을 한 날은 2025년 4월 22일이다.","scoring_points":["두 날짜 사이의 년·개월·주를 바르게 찾았는가","1년 = 12개월, 1주일 = 7일을 바르게 썼는가","날짜나 기간을 단위와 함께 바르게 썼는가"]},"explanation":["년이 바뀌면 년을, 월이 바뀌면 개월을 세요.","주는 7일씩 — 달의 날수도 따져요.","날짜와 기간을 단위와 함께 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_c#25','math',2,2,'u4','','g2_2_math_u4_review_c','unit_review','M2-2-u4-C10',4,'mc','auto','7월 26일에서 3주일 후는 몇 월 며칠인가요?',ARRAY['M2-2-u4-X18','M2-2-u4-X15']::text[],false,'{"seq":25,"concept":"M2-2-u4-C10","difficulty":4,"kind":"mc","stem":"7월 26일에서 3주일 후는 몇 월 며칠인가요?","options":[{"t":"8월 16일","correct":true},{"t":"7월 47일","mis":"M2-2-u4-X18"},{"t":"8월 17일","mis":"M2-2-u4-X18"},{"t":"7월 29일","mis":"M2-2-u4-X15"}],"explanation":["3주일은 21일이에요.","7월은 31일까지라 26일에서 5일 지나면 7월 31일이에요.","16일 더 지나면 8월 16일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#1','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C1',1,'sa','auto','시계가 나타내는 시각은 11시 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u4-C1","difficulty":1,"kind":"sa","stem":"시계가 나타내는 시각은 11시 몇 분인가요? 숫자로 쓰세요.","explanation":["짧은바늘이 11과 12 사이에 있으니 11시예요.","긴바늘이 숫자 5를 가리키니 5 × 5 = 25분이에요.","그래서 11시 25분이에요."],"variant_rule":{"tm":{"ask":"read","step":5}},"answer":["25"],"asset":{"type":"clock2","h":11,"m":25}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#2','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C1',1,'mc','auto','긴바늘이 숫자 11을 가리키면 몇 분인가요?',ARRAY['M2-2-u4-X02']::text[],true,'{"seq":2,"concept":"M2-2-u4-C1","difficulty":1,"kind":"mc","stem":"긴바늘이 숫자 11을 가리키면 몇 분인가요?","explanation":["숫자와 숫자 사이는 작은 눈금 5칸 — 5분이에요.","숫자 11까지 5분씩 11번이니 11 × 5 = 55예요.","그래서 55분이에요 — 숫자 그대로 11분이 아니에요."],"variant_rule":{"tm":{"ask":"numm"}},"options":[{"t":"55분","correct":true},{"t":"11분","mis":"M2-2-u4-X02"},{"t":"110분","mis":"M2-2-u4-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#3','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C2',1,'mc','auto','디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-2-u4-X06']::text[],true,'{"seq":3,"concept":"M2-2-u4-C2","difficulty":1,"kind":"mc","stem":"디지털시계의 시각을 바르게 읽은 것은 어느 것인가요?","explanation":["「:」 왼쪽은 시, 오른쪽은 분이에요.","3 : 08은 3시 8분이에요.","시는 「세 시」, 분은 「팔 분」으로 읽어요."],"variant_rule":{"tm":{"ask":"dig"}},"options":[{"t":"세 시 팔 분","correct":true},{"t":"팔 시 세 분","mis":"M2-2-u4-X06"},{"t":"삼 시 팔 분","mis":"M2-2-u4-X06"}],"asset":{"type":"digital","h":3,"m":8}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#4','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C3',1,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X05']::text[],true,'{"seq":4,"concept":"M2-2-u4-C3","difficulty":1,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 6과 7 사이에 있으니 6시예요.","긴바늘이 숫자 1(5분)에서 작은 눈금 2칸 더 간 곳이니 5 + 2 = 7분이에요.","그래서 6시 7분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"6시 7분","correct":true},{"t":"6시 8분","mis":"M2-2-u4-X04"},{"t":"6시 13분","mis":"M2-2-u4-X05"}],"asset":{"type":"clock2","h":6,"m":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#5','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C4',1,'sa','auto','11시 50분은 12시 몇 분 전인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-2-u4-C4","difficulty":1,"kind":"sa","stem":"11시 50분은 12시 몇 분 전인가요? 숫자로 쓰세요.","explanation":["11시 50분에서 10분이 지나면 12시가 돼요.","그래서 11시 50분을 12시 10분 전이라고도 해요.","「몇 시 전」의 시는 곧 될 정각 12시예요 — 지금 시 11시가 아니에요."],"variant_rule":{"tm":{"ask":"before"}},"answer":["10"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#6','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C5',1,'sa','auto','수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-2-u4-C5","difficulty":1,"kind":"sa","stem":"수영을 한 시간을 시간 띠에 나타냈어요. 수영을 하는 데 걸린 시간은 몇 분인가요? 숫자로 쓰세요.","explanation":["시작한 시각은 4시, 끝난 시각은 6시예요.","칠한 칸이 12칸 — 한 칸이 10분이니 120분이에요.","2시간은 60분씩 2번 — 120분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"bar"}},"answer":["120"],"asset":{"type":"tbar","from":[4,0],"to":[6,0],"label":"수영을 한 시간"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#7','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C7',1,'mc','auto','짧은바늘이 시계를 한 바퀴 도는 데 걸리는 시간은 몇 시간인가요?',ARRAY['M2-2-u4-X13','M2-2-u4-X01']::text[],false,'{"seq":7,"concept":"M2-2-u4-C7","difficulty":1,"kind":"mc","stem":"짧은바늘이 시계를 한 바퀴 도는 데 걸리는 시간은 몇 시간인가요?","options":[{"t":"12시간","correct":true},{"t":"24시간","mis":"M2-2-u4-X13"},{"t":"1시간","mis":"M2-2-u4-X01"}],"explanation":["짧은바늘은 1시간에 숫자 한 칸을 가요.","숫자는 12개예요.","그래서 한 바퀴는 12시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#8','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C8',1,'mc','auto','6월 9일은 무슨 요일인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":8,"concept":"M2-2-u4-C8","difficulty":1,"kind":"mc","stem":"6월 9일은 무슨 요일인가요?","explanation":["달력에서 9일을 찾아요.","9일이 있는 칸의 위를 따라 올라가면 화요일이에요.","같은 세로줄은 모두 같은 요일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"wday"}},"options":[{"t":"화요일","correct":true},{"t":"수요일","mis":"M2-2-u4-X17"},{"t":"월요일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":6,"start":1,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#9','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C4',2,'mc','auto','12시 5분 전은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X07','M2-2-u4-X08']::text[],true,'{"seq":9,"concept":"M2-2-u4-C4","difficulty":2,"kind":"mc","stem":"12시 5분 전은 몇 시 몇 분인가요?","explanation":["12시 5분 전은 12시가 되기 5분 전이에요.","12시에서 긴바늘을 5분만큼 거꾸로 돌리면 11시 55분이에요.","짧은바늘은 아직 11과 12 사이에 있어서 11시예요."],"variant_rule":{"tm":{"ask":"beforer"}},"options":[{"t":"11시 55분","correct":true},{"t":"12시 55분","mis":"M2-2-u4-X07"},{"t":"12시 5분","mis":"M2-2-u4-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#10','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',2,'mc','auto','1시간 25분은 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":10,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"1시간 25분은 몇 분인가요?","explanation":["1시간은 60분이에요.","1시간 25분 = 60분 + 25분이에요.","그래서 85분이에요 — 1시간을 100분으로 보면 안 돼요."],"variant_rule":{"tm":{"ask":"h60","form":"tomin"}},"options":[{"t":"85분","correct":true},{"t":"125분","mis":"M2-2-u4-X09"},{"t":"95분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#11','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',2,'mc','auto','150분은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":11,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"150분은 몇 시간 몇 분인가요?","explanation":["60분은 1시간이에요.","150분 = 120분 + 30분이에요.","120분은 2시간이니 2시간 30분이에요."],"variant_rule":{"tm":{"ask":"h60","form":"tohm"}},"options":[{"t":"2시간 30분","correct":true},{"t":"1시간 50분","mis":"M2-2-u4-X09"},{"t":"15시간","mis":"M2-2-u4-X09"},{"t":"2시간 40분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#12','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',2,'mc','auto','피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":12,"concept":"M2-2-u4-C6","difficulty":2,"kind":"mc","stem":"피아노 연습을 시작한 시각과 끝난 시각이에요. 피아노 연습을 하는 데 걸린 시간은 몇 시간 몇 분인가요?","explanation":["시작한 시각은 3시 30분, 끝난 시각은 5시 40분이에요.","3시 30분에서 1시간 뒤인 4시 30분을 먼저 찾고 남은 만큼 더 세면 2시간 10분이에요.","130분 = 2시간 10분이에요."],"variant_rule":{"tm":{"ask":"elapsed","form":"pair","unit":"hm"}},"options":[{"t":"2시간 10분","correct":true},{"t":"5시간 40분","mis":"M2-2-u4-X11"},{"t":"2시간 20분","mis":"M2-2-u4-X10"}],"asset":{"type":"dpair","a":[3,30],"b":[5,40]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#13','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C7',2,'sa','auto','1일 12시간은 몇 시간인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M2-2-u4-C7","difficulty":2,"kind":"sa","stem":"1일 12시간은 몇 시간인가요? 숫자로 쓰세요.","explanation":["하루는 24시간이에요 — 짧은바늘이 두 바퀴 돌아요.","1일 12시간 = 24시간 + 12시간이에요.","그래서 36시간이에요."],"variant_rule":{"tm":{"ask":"day","form":"toh"}},"answer":["36"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#14','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C7',2,'mc','auto','오전 8시에 피아노 연습을 시작해서 6시간 동안 했어요. 끝난 시각은 언제인가요?',ARRAY['M2-2-u4-X12']::text[],true,'{"seq":14,"concept":"M2-2-u4-C7","difficulty":2,"kind":"mc","stem":"오전 8시에 피아노 연습을 시작해서 6시간 동안 했어요. 끝난 시각은 언제인가요?","explanation":["낮 12시부터 밤 12시까지가 오후예요.","오전 8시에서 4시간 뒤가 낮 12시, 거기서 2시간 더 가면 오후 2시예요.","낮 12시를 지나면 오전이 오후로 바뀌어요."],"variant_rule":{"tm":{"ask":"ampm"}},"options":[{"t":"오후 2시","correct":true},{"t":"오전 2시","mis":"M2-2-u4-X12"},{"t":"오후 14시","mis":"M2-2-u4-X12"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#15','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C9',2,'sa','auto','2년은 몇 개월인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M2-2-u4-C9","difficulty":2,"kind":"sa","stem":"2년은 몇 개월인가요? 숫자로 쓰세요.","explanation":["1년은 12개월이에요.","2년은 12개월이 2번 — 24개월이에요.","그래서 24개월이에요."],"variant_rule":{"tm":{"ask":"units","form":"y2m"}},"answer":["24"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#16','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C8',2,'sa','auto','9월의 넷째 금요일은 며칠인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M2-2-u4-C8","difficulty":2,"kind":"sa","stem":"9월의 넷째 금요일은 며칠인가요? 숫자로 쓰세요.","explanation":["9월의 첫째 금요일은 4일이에요.","한 주에 7일씩 — 4, 11, 18, 25예요.","그래서 넷째 금요일은 25일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"nth"}},"answer":["25"],"asset":{"type":"cal","mon":9,"start":2,"days":30}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#17','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C3',3,'mc','auto','시계를 보고 몇 시 몇 분인지 고르세요.',ARRAY['M2-2-u4-X04','M2-2-u4-X03']::text[],true,'{"seq":17,"concept":"M2-2-u4-C3","difficulty":3,"kind":"mc","stem":"시계를 보고 몇 시 몇 분인지 고르세요.","explanation":["짧은바늘이 5와 6 사이에 있으니 5시예요.","긴바늘이 숫자 11(55분)에서 작은 눈금 3칸 더 간 곳이니 55 + 3 = 58분이에요.","그래서 5시 58분이에요."],"variant_rule":{"tm":{"ask":"read","step":1}},"options":[{"t":"5시 58분","correct":true},{"t":"5시 59분","mis":"M2-2-u4-X04"},{"t":"6시 58분","mis":"M2-2-u4-X03"},{"t":"5시 50분","mis":"M2-2-u4-X04"}],"asset":{"type":"clock2","h":5,"m":58}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#18','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',3,'mc','auto','1시 35분에 피아노 연습을 시작해서 1시간 40분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?',ARRAY['M2-2-u4-X09','M2-2-u4-X10']::text[],true,'{"seq":18,"concept":"M2-2-u4-C6","difficulty":3,"kind":"mc","stem":"1시 35분에 피아노 연습을 시작해서 1시간 40분 동안 했어요. 끝난 시각은 몇 시 몇 분인가요?","explanation":["시작한 시각 1시 35분에서 1시간 40분이 지난 시각을 찾아요.","1시간 뒤는 2시 35분, 거기서 40분 더 지나면 3시 15분이에요.","분이 60분이 되면 시가 하나 커져요."],"variant_rule":{"tm":{"ask":"after"}},"options":[{"t":"3시 15분","correct":true},{"t":"2시 75분","mis":"M2-2-u4-X09"},{"t":"3시 25분","mis":"M2-2-u4-X10"},{"t":"3시 5분","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#19','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C8',3,'mc','auto','5월 20일에서 8일 전은 며칠인가요?',ARRAY['M2-2-u4-X17']::text[],true,'{"seq":19,"concept":"M2-2-u4-C8","difficulty":3,"kind":"mc","stem":"5월 20일에서 8일 전은 며칠인가요?","explanation":["20일은 빼고 전날부터 하루씩 세어요.","20 − 8 = 12예요.","그래서 5월 12일이에요."],"variant_rule":{"tm":{"ask":"cal","form":"before"}},"options":[{"t":"12일","correct":true},{"t":"13일","mis":"M2-2-u4-X17"},{"t":"11일","mis":"M2-2-u4-X17"},{"t":"5일","mis":"M2-2-u4-X17"}],"asset":{"type":"cal","mon":5,"start":5,"days":31}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#20','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C10',3,'mc','auto','2024년 12월 1일에 수영을 배우고 3주 후에 스케이트를 탔어요. 스케이트를 탄 날은 언제인가요?',ARRAY['M2-2-u4-X15','M2-2-u4-X14']::text[],false,'{"seq":20,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"2024년 12월 1일에 수영을 배우고 3주 후에 스케이트를 탔어요. 스케이트를 탄 날은 언제인가요?","options":[{"t":"2024년 12월 22일","correct":true},{"t":"2024년 12월 4일","mis":"M2-2-u4-X15"},{"t":"2025년 3월 1일","mis":"M2-2-u4-X14"}],"explanation":["3주는 7일이 3번 — 21일이에요.","1 + 21 = 22예요.","그래서 2024년 12월 22일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#21','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C10',3,'mc','auto','방학식은 7월 24일이에요. 오늘이 7월 10일이면 방학식까지 며칠 남았나요?',ARRAY['M2-2-u4-X17','M2-2-u4-X14']::text[],false,'{"seq":21,"concept":"M2-2-u4-C10","difficulty":3,"kind":"mc","stem":"방학식은 7월 24일이에요. 오늘이 7월 10일이면 방학식까지 며칠 남았나요?","options":[{"t":"14일","correct":true},{"t":"15일","mis":"M2-2-u4-X17"},{"t":"24일","mis":"M2-2-u4-X14"}],"explanation":["오늘은 빼고 내일부터 하루씩 세요.","24 − 10 = 14예요.","그래서 14일 남았어요 — 디데이 14일 전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#22','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C5',3,'mc','auto','7시 10분에서 9시 10분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?',ARRAY['M2-2-u4-X11','M2-2-u4-X10']::text[],true,'{"seq":22,"concept":"M2-2-u4-C5","difficulty":3,"kind":"mc","stem":"7시 10분에서 9시 10분이 될 때까지 긴바늘은 몇 바퀴 돌았나요?","explanation":["긴바늘이 한 바퀴 돌면 60분 — 1시간이 지나요.","7시 10분부터 9시 10분까지 2시간이 지났어요.","그래서 긴바늘은 2바퀴 돌았어요."],"variant_rule":{"tm":{"ask":"laps"}},"options":[{"t":"2바퀴","correct":true},{"t":"9바퀴","mis":"M2-2-u4-X11"},{"t":"3바퀴","mis":"M2-2-u4-X10"},{"t":"1바퀴","mis":"M2-2-u4-X10"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#23','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C6',4,'essay','teacher','「1시간 = 60분」을 쓰는 까닭을 시계의 두 바늘로 설명하고, 2시간 30분은 몇 분인지 구해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u4-C6","difficulty":4,"kind":"essay","stem":"「1시간 = 60분」을 쓰는 까닭을 시계의 두 바늘로 설명하고, 2시간 30분은 몇 분인지 구해 보세요.","answer_guide":{"answer":"예: 긴바늘이 한 바퀴 돌면 60분이 지나고 그동안 짧은바늘은 숫자 한 칸을 가서 1시간이 지난다. 그래서 1시간 = 60분이다. 2시간 30분은 60 + 60 + 30 = 150분이다.","scoring_points":["긴바늘 한 바퀴가 60분임을 썼는가","짧은바늘 한 칸이 1시간임을 썼는가","150분이라고 구했는가"]},"explanation":["긴바늘 한 바퀴 = 60분이에요.","그동안 짧은바늘 한 칸 = 1시간이에요.","2시간 30분 = 60 + 60 + 30 = 150분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#24','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C10',4,'essay','teacher','오늘은 10월 12일이고 내 생일은 11월 2일이에요. 생일까지 며칠 남았는지 달력으로 세는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u4-C10","difficulty":4,"kind":"essay","stem":"오늘은 10월 12일이고 내 생일은 11월 2일이에요. 생일까지 며칠 남았는지 달력으로 세는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 오늘은 빼고 센다. 10월은 31일까지라 10월 12일에서 10월 31일까지 19일, 11월 1일과 2일이 2일이므로 19 + 2 = 21일 남았다.","scoring_points":["두 날짜 사이의 년·개월·주를 바르게 찾았는가","1년 = 12개월, 1주일 = 7일을 바르게 썼는가","날짜나 기간을 단위와 함께 바르게 썼는가"]},"explanation":["년이 바뀌면 년을, 월이 바뀌면 개월을 세요.","주는 7일씩 — 달의 날수도 따져요.","날짜와 기간을 단위와 함께 바르게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u4_review_d#25','math',2,2,'u4','','g2_2_math_u4_review_d','unit_review','M2-2-u4-C10',4,'mc','auto','10월 20일에서 2주일 후는 몇 월 며칠인가요?',ARRAY['M2-2-u4-X18','M2-2-u4-X15']::text[],false,'{"seq":25,"concept":"M2-2-u4-C10","difficulty":4,"kind":"mc","stem":"10월 20일에서 2주일 후는 몇 월 며칠인가요?","options":[{"t":"11월 3일","correct":true},{"t":"11월 4일","mis":"M2-2-u4-X18"},{"t":"10월 34일","mis":"M2-2-u4-X18"},{"t":"10월 22일","mis":"M2-2-u4-X15"}],"explanation":["2주일은 14일이에요.","10월은 31일까지라 20일에서 11일 지나면 10월 31일이에요.","3일 더 지나면 11월 3일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
